SKILL_DETAIL_DESC[23] = "^ffffff快速的朝一個方向挪移，可以用來躲閃攻擊。使用需要消耗體力，且短時無法再次使用。在空中使用移步換形時，可以位移更遠的距離，相對應也會消耗額外體力並且較長時間無法再次使用。"
