SKILL_TIP_REMARK[797] = "^D7C4A2少林門派在長期的苦修中悟得的基礎身法，能夠迅速向後跳躍，躲掉來自前方的攻擊。"
SKILL_TIP_REMARK[798] = "^D7C4A2少林門派的輕身功夫，使用後會獲得短暫加速效果。"
SKILL_TIP_REMARK[799] = "^D7C4A2少林門派採用守勢時使用的架構，增加防禦力和破綻上限，但是減緩移動速度，能派生使用各種閃躲招式。"
SKILL_TIP_REMARK[800] = "^D7C4A2少林門派最常用的招式架構，使用棍棒為武器，無特殊效果。"
SKILL_TIP_REMARK[801] = "^D7C4A2少林門派特殊的招式架構，將棍棒展開為三段增加攻擊範圍，略微減少傷害。"
SKILL_TIP_REMARK[802] = "^D7C4A2少林門派各種拳掌招式所用架構，貼身短打，但更加靈活且變化豐富。"
SKILL_DETAIL_DESC[803] = "^ffffff切換到使用長棍攻擊的戰鬥姿態，可以使用武學“普渡杖法”的全部招式。"
SKILL_DETAIL_DESC[804] = "^ffffff切換到使用三節棍攻擊的戰鬥姿態，可以使用武學“韋陀棍法”的全部招式。"
SKILL_DETAIL_DESC[805] = "^ffffff切換到空手拳掌攻擊的戰鬥姿態，可以使用武學“羅漢拳”的全部招式。"
SKILL_DETAIL_DESC[834] = "^ffffff揮劍迅速穿刺目標後，接連多次穿刺，最後給予奮力一擊。"
