SKILL_DETAIL_DESC[4591] = "^ffffff雙手置於胸前大力散射，對目標及其周圍造成單次傷害，命中後的爆破效果能夠讓單位防禦崩壞，降低其外功護甲。"
SKILL_DETAIL_DESC[4592] = "^ffffff向敵人所處位置噴射一枚毒氣機關，擊中後在目的地區域散播毒霧效果，霧中的單位會受到較大傷害。"
