SKILL_DETAIL_DESC[4594] = "^ffffff疾如風、徐如影。迅速閃身翻滾躲避當前攻擊，以疾風之勢瞬移至他處，同時在原地丟下分身假像。"
SKILL_DETAIL_DESC[4595] = "^ffffff淩空倒立旋轉射擊，對周圍目標造成巨大傷害，並能附帶擊暈效果。"
SKILL_DETAIL_DESC[4596] = "^ffffff基本的峨嵋炎陽掌擊，造成兩次單體遠程傷害。"
SKILL_DETAIL_DESC[4597] = "^ffffff凝聚全身氣力弓步雙手推掌，向敵人擊出赤砂掌勁，可對選中目標周圍多個單位造成單次傷害。"
SKILL_DETAIL_DESC[4598] = "^ffffff側身抽擊，讓敵人元神虛弱，降低其內功攻擊和內攻防禦。"
SKILL_DETAIL_DESC[4599] = "^ffffff安神撫心，對自身施放療傷術，回復少量氣血。"
SKILL_DETAIL_DESC[4600] = "^ffffff原地旋轉起舞，在自身所處位置周圍降下天雷。對範圍內敵人產生傷害的同時，還可一定時間內禁止其使用絕招。"
SKILL_DETAIL_DESC[4601] = "^ffffff異常強大的恢復能力，使用後對自身周圍6米內的玩家施放療傷效果，可以回復大量氣血值。"
