SKILL_DETAIL_DESC[2928] = "^ffffff用劍法形成熾熱的火環，對前方的單位發動攻擊，可以將擊中的敵人擊退聚集起來，過程中無視移動限制狀態影響。此絕技可以在空中使用。"
