SKILL_DETAIL_DESC[4691] = "^ffffff以淩厲的攻勢對敵人發動剛體亂舞攻擊，一共掃出七劍，每劍都會使目標定身，最後一劍會發出氣波，對前方直線敵人造成巨大傷害並擊退。"
SKILL_DETAIL_DESC[2913] = "^ffffff對敵人刺出一劍，並連續旋轉吸附攻擊，過程中免疫移動限制狀態影響，連打可以增加時間，最後用剛體下掃腿追擊，可使露出弱點的目標倒地。"
