SKILL_DETAIL_DESC[4711] = "^ffffff一閃必殺，疾速閃身到目標背後，使其不能移動，並造成抓取判定傷害。一閃擊中後，一段時間內的蓄力技能均可以移動蓄力。"
SKILL_DETAIL_DESC[4712] = "^ffffff用雙劍同時斬擊敵方，對其造成定身，中時蓄力一段可以追加三連斬，長時蓄力二段可以追加剛體亂舞上挑攻擊，將露出弱點的敵人擊飛。"
SKILL_DETAIL_DESC[4713] = "^ffffff用快速的劍法斬擊敵人，造成遲緩效果，短時蓄力一段可追加一劍，使敵人遲緩更長時間，中時蓄力二段則衝鋒至敵人身前身後各攻擊一次，且背後的攻擊無法被格擋。"
SKILL_DETAIL_DESC[4714] = "^ffffff雙劍連砍向敵人發動斬擊，擊中使敵人定身，中時蓄力一段後會追加三連刺，長時蓄力二段後會追加剛體三連踢擊重劈，將露出弱點的敵人擊倒。"
SKILL_DETAIL_DESC[4715] = "^ffffff用無法看清的刀法連續拔出數劍，連續擊中八次後可以用更快的剛體六連刺，將前方所有的敵人擊退。"
SKILL_DETAIL_DESC[4716] = "^ffffff快速拔刀對周圍的敵人進行攻擊，短時蓄力一段則將變招為原地4段旋風攻擊，中時蓄力二段後則會變成8段旋風攻擊，且旋風攻擊過程中可以移動，免疫限制類狀態影響。"
SKILL_DETAIL_DESC[2877] = "^ffffff以幻影對敵人進行攻擊，對前方的敵人造成內功傷害。"
SKILL_DETAIL_DESC[2878] = "^ffffff以幻影對敵人進行攻擊，對前方的敵人造成內功傷害。"
SKILL_DETAIL_DESC[2879] = "^ffffff以幻影對敵人進行攻擊，對前方的敵人造成內功傷害。"
SKILL_DETAIL_DESC[2844] = "^ffffff以幻影對敵人進行攻擊，對前方的敵人造成內功傷害。"
SKILL_DETAIL_DESC[2875] = "^ffffff用幻影般的劍術向朝前方推出三個幻影劍氣，對敵人造成傷害，並將目標擊退。"
SKILL_DETAIL_DESC[4717] = "^ffffff絕技有兩種特性：如果輕觸按鍵，會以迷惑性的幻影浮擊敵人將其擊退，自身留原地；如果長按按鍵，幻影留原地，自身沖出刺殺敵人將其點穴，並追加背擊，造成大量傷害。"
SKILL_DETAIL_DESC[4718] = "^ffffff絕技有兩種特性：如果輕觸按鍵，會以迷惑性的跳躍幻影攻擊敵人將擊擊退，自身留原地；如果長按按鍵，幻影留原地，自身跳躍衝擊目標，使其定身，並造成大量傷害。"
SKILL_DETAIL_DESC[4719] = "^ffffff向前方推出幻影三連打，對敵人造成連環撞擊。並且可以跟隨按鍵時間長短，讓自身跟隨幻影進行追擊。按滿可以讓自身衝撞到最遠將目標挑暈，同時可將露出弱點的敵人擊飛。"
SKILL_DETAIL_DESC[4720] = "^ffffff施放絕技後立刻隱身，隨即產生一個幻影跳躍劈擊敵人，並使其遲緩。如果不鬆手，將位移到目標上方以流星墜地之勢攻擊敵人，將露出弱點的單位擊倒。絕技施放過程可移動，無視移動限制狀態，並可以在空中使用。"
