SKILL_DETAIL_DESC[1036] = "^ffffff將雙刀如幻影般的扔出，對前方敵人造成連續傷害。後兩招無法格擋，合招時全身剛體。"
SKILL_DETAIL_DESC[1043] = "^ffffff將雙刀如幻影般的扔出，對前方敵人造成連續傷害。後兩招無法格擋，合招時全身剛體。"
SKILL_DETAIL_DESC[4078] = "^ffffff將雙刀如幻影般的扔出，對前方敵人造成連續傷害。後兩招無法格擋，合招時全身剛體。"
SKILL_DETAIL_DESC[4086] = "^ffffff快速奔襲至目標背後，對目標造成外功傷害，並使目標定身。絕技可以在空中使用。"
SKILL_DETAIL_DESC[4085] = "^ffffff以幻影刀法瞬移至目標身前連砍數刀，最後一刀將使目標陷入點穴狀態，然後再瞬間回到原位。"
SKILL_DETAIL_DESC[4899] = "^ffffff用雙刀交叉於身前蓄力，然後將前方敵人擊飛，蓄力時間越長擊飛效果越強。蓄力過程中為當身狀態，如果受到攻擊，將一躍而起連踩攻擊者數次再將踢開，此絕技為抓取判定。"
