SKILL_DETAIL_DESC[4904] = "^ffffff將雙刀用鐵鍊固定，並向蘊足內力扔出，對前方的敵人造成內功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[4905] = "^ffffff用膝蓋對前方的敵人連頂二次，可將露出弱點的敵人擊飛。"
SKILL_DETAIL_DESC[2988] = "^ffffff將鏈刃掄圓，再向前方地面猛砸，造成巨大傷害，蓄力可以增加傷害，可以將露出弱點的敵人擊倒。"
SKILL_DETAIL_DESC[2989] = "^ffffff把鏈刃扔處纏住對方，并用業火對其及周圍目標進行焚燒，造成數次傷害。此絕技為抓取判定。"
SKILL_DETAIL_DESC[4088] = "^ffffff以蛇行之勢鏟至目標身前，並對旋風腿和倒鉤踢擊進行追擊，最後一擊可將露出弱點的敵人擊飛。"
SKILL_DETAIL_DESC[2936] = "^ffffff將鏈刃前方地面推出並收回，對敵人造成傷害，收回的一次攻擊無法格擋。熾熱的鏈刃同時將引燃地面，可以使在區域內的敵人定身。"
SKILL_DETAIL_DESC[3030] = "^ffffff一躍而起，用快速的行動向目標突刺攻擊，落地瞬間全身剛體。此絕技可以在空中使用。"
SKILL_DETAIL_DESC[4906] = "^ffffff向周圍連續三次甩動鏈刃，以巨大的火焰車輪對周圍進行攻擊，同時使受傷的目標遲緩。出招過程中全身剛體。"
SKILL_DETAIL_DESC[4749] = "^ffffff用淩勵的鞭法對前方大範圍敵人進行掃擊，造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[2201] = "^ffffff用淩勵的鞭法對前方大範圍敵人進行掃擊，造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[4750] = "^ffffff用淩勵的鞭法對前方大範圍敵人進行掃擊，造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[2064] = "^ffffff用淩勵的鞭法對前方大範圍敵人進行掃擊，造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[4751] = "^ffffff將鞭索套住敵人，施用巧勁將敵人甩至身後。此絕技為抓取判定。"
SKILL_DETAIL_DESC[2062] = "^ffffff一躍而起對近處的敵人推擊，可以自身身前的敵人擊退。"
SKILL_DETAIL_DESC[4752] = "^ffffff甩鞭對遠方的敵人抽擊，造成遲緩效果。如果蓄力後抽擊，遲緩的效果會更高，時間也將更長。"
SKILL_DETAIL_DESC[4753] = "^ffffff以圓舞步旋轉攻擊敵人，其間自身可以自由移動，過程中無視移動限制狀態影響。此絕技可在空中使用。"
SKILL_DETAIL_DESC[4754] = "^ffffff由幻影鐵索提至空中，然後瞬間從敵人身邊落下，可將露出弱點的敵人擊倒。下落時為全身剛體狀態。此絕技可在空中使用。"
SKILL_DETAIL_DESC[4755] = "^ffffff用快速的鞭擊抽擊敵人，連打次數趕越多速度越快，如果擊打超過10次將發動剛體重擊，將身前的敵人擊飛。"
