SKILL_DETAIL_DESC[4763] = "^ffffff用快速鞭法對身邊的敵人攻擊，造成內功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[4764] = "^ffffff用快速鞭法對身邊的敵人攻擊，造成內功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[4756] = "^ffffff用快速鞭法對身邊的敵人攻擊，造成內功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[4757] = "^ffffff召喚出一朵毒花，施放3只慢速的飛蛾攻擊敵人，對目標造成擊退。"
SKILL_DETAIL_DESC[4758] = "^ffffff於足下召喚出一片霧粉組成的區域，對使進入區域的敵人造成傷害，同時有機率受到定身狀態影響。此絕技可在空中使用。"
SKILL_DETAIL_DESC[4759] = "^ffffff以仙狐之力附體，全身保持剛體狀態，並旋轉舞動一周進行強裂的毒爆，可以將周圍露出弱點的敵人飛。"
SKILL_DETAIL_DESC[4760] = "^ffffff於足下召出血炎蛇，血炎蛇將噴處火霧結成一片，對進入區域的敵人造成，同時敵人會受到灼燒狀態影響，持續損失生命值。此絕技可在空中使用。"
SKILL_DETAIL_DESC[4761] = "^ffffff於足下召出一朵寒玉花，寒玉花將引來無數寒冰蟲攻擊進入區域的目標，對其造成傷害，同時對其造成冰寒狀態，並有一定機率對其造成冰凍狀態影響。此絕技可在空中使用。"
SKILL_DETAIL_DESC[1086] = "^ffffff扔出一個爆炸蠱，短暫延時後造成巨大爆炸，將目的地區域內的敵人定身。蟲蠱爆炸後將在原地形成一片毒區域，使區域內的敵人持續受到傷害。"
SKILL_DETAIL_DESC[4778] = "^ffffff用冰球攻擊敵人，對敵人造成成內功傷害。冰球擊中後使敵人陷入冰寒狀態。"
SKILL_DETAIL_DESC[4779] = "^ffffff用冰球攻擊敵人，對敵人造成成內功傷害。冰球擊中後使敵人陷入冰寒狀態。"
SKILL_DETAIL_DESC[4780] = "^ffffff用冰球攻擊敵人，對敵人造成成內功傷害。冰球擊中後使敵人陷入冰寒狀態。"
SKILL_DETAIL_DESC[4781] = "^ffffff用冰球攻擊敵人，對敵人造成成內功傷害。冰球擊中後使敵人陷入冰寒狀態。"
SKILL_DETAIL_DESC[2245] = "^ffffff在前方頂起無相盾，可以擊退敵人。如果在已經有無相盾的情況下，可以將其轉化成一道冰波攻擊前方敵人，可以使目標陷入冰寒狀態。"
SKILL_DETAIL_DESC[4782] = "^ffffff在遠方畫出一塊冰陣，短暫的延時後，冰陣將轉化為巨大的冰塊，使敵人進入凍結狀態。"
SKILL_DETAIL_DESC[2244] = "^ffffff在前方頂起無相盾，可以擊退敵人。如果在已經有無相盾的情況下，可以將其踢碎，使對方陷入冰寒，並將目標擊退。絕技可將露出弱點的敵人擊飛。"
SKILL_DETAIL_DESC[862] = "^ffffff召喚一陣冰雨攻擊目的地區域的敵人，可以造成冰寒效果，連按可以持續攻擊數次。"
SKILL_DETAIL_DESC[2246] = "^ffffff在前方頂起無相盾，可以擊退敵人。如果在已經有無相盾的情況下，可以可以將其踢碎身向後反彈，並使前方的目標定身。絕技可將露出弱點的敵人擊飛。"
SKILL_DETAIL_DESC[2248] = "^ffffff在前方頂起無相盾，可以擊退敵人。如果在已經有無相盾的情況下，可以頂著盾向前衝刺一段距離，將前方的怪物聚至一處。"
SKILL_DETAIL_DESC[2239] = "^ffffff用扇子攻擊敵人，對其造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[2230] = "^ffffff用扇子攻擊敵人，對其造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[2232] = "^ffffff用扇子攻擊敵人，對其造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[2233] = "^ffffff用扇子攻擊敵人，對其造成外功傷害。合招時全身剛體。"
SKILL_DETAIL_DESC[860] = "^ffffff向前衝刺攻擊敵人，對其造成成外功傷害。"
SKILL_DETAIL_DESC[878] = "^ffffff向前衝刺攻擊敵人，對其造成成外功傷害。"
SKILL_DETAIL_DESC[4783] = "^ffffff快速沖至敵人身邊，將其抓住後進快速攻擊並借火焰之力踢飛。此絕技為抓取判定。"
SKILL_DETAIL_DESC[2241] = "^ffffff對前方敵人進行快速的下段掃踢，可將敵人攻擊倒地。"
SKILL_DETAIL_DESC[2242] = "^ffffff將扇子拋出環繞自已一周，可以使環繞自身一周的敵人全部進入點穴狀態。"
SKILL_DETAIL_DESC[871] = "^ffffff反身一躍至目標身邊，可以將露出弱點的敵人攻擊倒地。此招可以在空中使用。"
SKILL_DETAIL_DESC[4784] = "^ffffff以倒拔垂楊柳之勢對敵人進行剛體攻擊，如果在空中使用，則可以在此之前數次連續踩踏敵人，所有攻擊均會將露出弱點的敵人擊倒。此絕技可在空中使用，空中使用時無視移動限制狀態影響。"
SKILL_DETAIL_DESC[875] = "^ffffff將扇子向前方扔出並收回，對敵人造成傷害和遲緩狀態，扇子飛回時時的攻擊無法被格擋。"
SKILL_DETAIL_DESC[4173] = "^ffffff對目標連續射擊數次，造成外功攻擊。如果目標太近，合招攻擊前自身會先後滾翻再射擊。"
