SKILL_DETAIL_DESC[920] = "^ffffff對目標連續射擊數次，造成外功攻擊。如果目標太近，合招攻擊前自身會先後滾翻再射擊。"
SKILL_DETAIL_DESC[929] = "^ffffff對目標連續射擊數次，造成外功攻擊。如果目標太近，合招攻擊前自身會先後滾翻再射擊。"
SKILL_DETAIL_DESC[4185] = "^ffffff前躍腿法夾擊，將目標拋向空中，用雙槍連續猛擊並一槍擊飛。此絕技為抓取判定，並且可在空中使用。"
SKILL_DETAIL_DESC[921] = "^ffffff雙爪合一向身前丟射飛盤暗器，對前方敵人造成撞擊傷害，並將敵人擊退。"
SKILL_DETAIL_DESC[931] = "^ffffff向敵人扔出一枚蜘蛛雷，可以對目標周圍造成傷害，蜘蛛雷稍後會展開並形成機關蛛網，使停留在附近的單位遲緩。該絕招可以在空中使用。"
SKILL_DETAIL_DESC[2617] = "^ffffff扔出一枚金蛇爪器，對目標造成傷害，並對其產生纏繞效果，使其無法移動。"
SKILL_DETAIL_DESC[2620] = "^ffffff在自身周圍暴風驟雨般的狂亂射擊，對周圍的敵人造成多次傷害判定，使露出弱點的敵人產成硬直。出招時全程剛體。"
SKILL_DETAIL_DESC[2618] = "^ffffff以繚亂的槍法對身前目標點射，射擊方向的目標會受到撞擊傷害。可對露出弱點的敵人造成硬直。過程中自已可以隨意移動，並且無視移動限制狀態影響。"
SKILL_DETAIL_DESC[4188] = "^ffffff對目標發射連續的雷火炮，造成範圍內功傷害。"
SKILL_DETAIL_DESC[2622] = "^ffffff槍管中噴射出一隻燃燒的機械飛禽，可以將前方的敵人擊退。消耗1枚火龍彈。此絕技可在空中使用。"
SKILL_DETAIL_DESC[926] = "^ffffff原地蓄力向槍管中填充強效火藥，向身前發射一枚產生巨大爆炸的火炮，蓄力時間越久傷害越大，同時可以將露出弱點的敵人擊飛。消耗1枚火龍彈。"
SKILL_DETAIL_DESC[2827] = "^ffffff在腳下放置金刀雷陣，如被踩中將爆炸，使敵人定身，並將露出弱點的敵人擊飛。消耗1枚火龍彈。"
SKILL_DETAIL_DESC[2624] = "^ffffff超遠距離的瞄準射擊，對目標發射飛彈進行狙擊，使擊中的敵人進入點穴狀態。更長時間的瞄準可以讓傷害爆發更高。"
SKILL_DETAIL_DESC[4183] = "^ffffff將暗器炮筒裝上多重鏢孔，向目的地區域發射一串鏢彈，在空中將會進一步分裂成多枚箭矢攻擊地面，擊中的敵人會被遲緩。消耗1枚火龍彈。"
SKILL_DETAIL_DESC[2828] = "^ffffff“亂石飛沙眼迷離”。向敵人發射一枚煙霧彈，使煙霧區域內的敵人視野大大縮小。消耗1枚火龍彈。"
SKILL_DETAIL_DESC[2627] = "^ffffff對前方進行火焰噴射，造成傷害同時也將使目標燃燒，蓄力越長，火焰噴射範圍將更為聚集。蓄滿時噴火過程全程剛體。"
