SKILL_DETAIL_DESC[6084] = "^ffffff向前方吐火，使命中的敵人大大減速。"
SKILL_DETAIL_DESC[6085] = "^ffffff用隱藏的匕首向目標攻擊。"
SKILL_DETAIL_DESC[6086] = "^ffffff將鉤扔出將目標拉至身前。"
SKILL_DETAIL_DESC[6087] = "^ffffff啟動後對周圍單位造成傷害並減速。"
SKILL_DETAIL_DESC[6088] = "^ffffff擊殺敵人後獲得生命值加成。"
SKILL_DETAIL_DESC[6089] = "^ffffff用刀刺擊敵人並使敵我均長時無法動彈。"
SKILL_DETAIL_DESC[6090] = "^ffffff用幻影深入院方的敵陣攻擊後並返回。"
SKILL_DETAIL_DESC[6091] = "^ffffff向近身敵人發動刀斬襲擊。"
SKILL_DETAIL_DESC[6092] = "^ffffff攻擊時使敵人消減內力值。"
SKILL_DETAIL_DESC[6093] = "^ffffff瞬間移動到目的地區域。"
SKILL_DETAIL_DESC[6094] = "^ffffff為自已增加護盾，吸收內功傷害。"
SKILL_DETAIL_DESC[6095] = "^ffffff對敵人造成傷害，並視其損失的內力造成額外傷害"
SKILL_DETAIL_DESC[6096] = "^ffffff向周圍的敵人發動狂亂攻擊。"
SKILL_DETAIL_DESC[6097] = "^ffffff用鐵拳對敵人發動攻擊"
SKILL_DETAIL_DESC[6098] = "^ffffff向目的地區域扔出大量垃圾使其眩暈。"
SKILL_DETAIL_DESC[6099] = "^ffffff以敵人無法預料的力量將前方敵人投擲起來。"
SKILL_DETAIL_DESC[6100] = "^ffffff增加自已的防禦，並使近戰敵人眩暈（未實現）"
SKILL_DETAIL_DESC[6101] = "^ffffff返老還童，極大的增加體形和傷害，但降低攻速。"
SKILL_DETAIL_DESC[6102] = "^ffffff快速旋轉，用火焰之力攻擊周圍敵人。"
SKILL_DETAIL_DESC[6104] = "^ffffff    少林弟子，慈悲為懷，為少增殺戮，常以木棍為器。只可惜江湖險惡，執迷不悟者眾，難以普渡者不知凡幾。然，懲惡即是揚善，菩薩亦有金剛之怒，昔有少林高僧，為懲惡徒，以《易筋》《洗髓》兩經為源，創此神功。\r    此棍法使出時，如萬佛誦經，諸邪難近，凡身側十米內之敵，皆遭重創。招數用盡後，怒氣平息，怒氣值歸零"
SKILL_DETAIL_DESC[6105] = "^ffffff    昔有人皇伏羲，創先天八卦：“易有太極，是生兩儀，兩儀生四象，四象生八卦，八卦之數，則衍生世間萬象”。百餘年前，有武當道人，以此為源，演化出此劍法。\r    絕招使出時，可重創近身遭十米內敵人。招數用盡後，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[6106] = "^ffffff    “吾善養吾浩然之氣”，亞聖養氣，浩然於天地之間，養吾劍法乃華山氣宗登峰造極之術。老子曰：“視之不見名曰夷，聽之不聞名曰希”，希夷劍法，劍意隨心，不拘一格，乃華山劍宗之絕招。數十年前，有華山長老，于思過崖前悔過，無意間融兩宗武學於一身，創此絕招。\r     此劍法使出時，劍氣縱橫，氣沖鬥牛，身遭十米內敵手皆遭重傷。只可惜劍招使完後，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[6107] = "^ffffff    一劍抖春寒，萬花皆飄零。恒山北接塞外，春暖常遲，縱花開萬朵，蕭風南襲時，也化作落紅朵朵，遍地春泥。昔有恒山隱世高手，觀落花之姿，創萬花飄零劍法。\r    此劍法使出時，威力驚人，身旁十米之內，萬物蕭索，人畜皆傷，縱是江湖高手，也難逃一命。劍招用盡之時，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[6108] = "^ffffff    祝融起灶，造南嶽五神峰。昔有衡山長老，辟谷於南嶽芙蓉、紫蓋、石廩、天柱、祝融五峰之間，窮甲子功力，創此衡山派最強劍法。\r    此絕招使出時，如火神鑄劍，威力驚人。近身十米之內之敵，皆難逃命。只可惜劍招用盡之時，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[6109] = "^ffffff    百餘年前，中土忽現天竺怪客，身背雙刀，怒不可遏，長城內外，鮮有敵手。又經三十年，天竺怪客隱匿於江湖，口口相傳，其人實乃日月神教長老也。\r    此絕招使出時，如日月經天、光芒萬丈，十米之內生靈，皆遭重創，難以生還。然招數用老之際，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[6110] = "^ffffff    紅顏柔骨，傾心一世。南疆子女，敢愛敢恨，若與心上人結上心蠱，則永世不變。然世間寡情薄意者眾，相守一生者寥寥。昔有教中蠱婆，被負心人傷，創此腐骨穿心鞭法。\r    此鞭法使出時，如萬蠱鑽心，實難抵擋，身遭十米內敵手，皆受重創，難以活命。不過在招數用老之際，怒氣平息，怒氣值將歸零。"
SKILL_DETAIL_DESC[6111] = "^ffffff    北冥有魚，其名為鯤。化而為鳥，其名為鵬。鯤鵬逍遙於滄海天際間，不知幾千萬裡也。昔有逍遙長老，以《莊子.逍遙遊》篇為引，憑其造化自然無上功力，創此神功。\r    此功使出時，一扇揮出，天地混沌為之而散，威力驚人。但凡周遭十米內之敵，皆遭重創。只可惜招式用盡之際，怒氣平息，怒氣值將歸零。"
SKILL_DETAIL_DESC[6112] = "^ffffff    昔有唐門宗老，為同門所妒，逐出門庭。二十年間，嘗盡人間淒苦。後遊歷酆都鬼城，觀地獄之變，恍然大悟。以平生之怒，創十八地獄爪，重奪唐門宗主之位。\r    此絕招威力驚人，絕招使出時，十米之內生靈，或成齏粉，或重傷保命。只不過招式用盡之時，怒氣將熄，怒氣值歸零。"
SKILL_DETAIL_DESC[6113] = "^ffffff    南宋末年，峨嵋創派祖師郭襄與昆侖道人何足道相約賞雪。郭襄女俠觀飄雪之態，悟出“峨嵋飄雪”三絕招，何足道憶昆侖山之雄態，以三招“昆侖穿雲”掌回應之。後峨嵋歷代掌門，窮其心力，將兩大宗師絕學融合，創此絕招。\r    此招擊出時，如飄雪穿雲，又如金頂佛光，威力之大，不可小覷。周身十米內，皆籠罩在杖影之下，難有僥倖活命者。然，招數用老時，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[11368] = "^ffffff   玲瓏弟子兩種形態加于一身，在千鈞一發之際，雙身共存，合力圍成的陣法。\r    此絕招使出時，能使千軍萬馬動彈不得。 然，招數用老時，怒氣平息，怒氣值歸零。"
SKILL_DETAIL_DESC[6114] = "^ffffff在倒地狀態中，使自身能夠迅速起身恢復站立姿勢，並短時間剛體效果。"
SKILL_TIP_REMARK[6114] = "^D7C4A2被擊倒時，默認快速鍵為按^1EFF00空白鍵^D7C4A2。"
SKILL_DETAIL_DESC[6115] = "^ffffff在空中被擊飛狀態中，使自身能夠迅速調整平衡，向特定方向彈出，有機會避免可能受到的更多連擊攻擊。"
SKILL_TIP_REMARK[6115] = "^D7C4A2被浮空時，默認快速鍵為按^1EFF00空白鍵^D7C4A2。"
