SKILL_DETAIL_DESC[6142] = "^ffffff習得真訣，激發絕技潛力，凝聚全身真氣後提升絕技境界至極限，使用真訣時全身剛體同時絕技形態也發生改變，造成巨大傷害。\r（真訣效果在比武場中會受到調整。）"
