SKILL_DETAIL_DESC[9106] = "^ffffff腳底抹油，向著羊村奔跑吧。持續15秒的加速跑。"
SKILL_DETAIL_DESC[9297] = "^ffffff冷卻：90秒\r\r長約一尺的小標槍。"
SKILL_DETAIL_DESC[9298] = "^ffffff冷卻：90秒\r\r銅錢磨利邊緣而成，比普通飛鏢的殺傷力稍大一些。"
SKILL_DETAIL_DESC[9299] = "^ffffff冷卻：90秒\r\r前面為尖頭梅花棱的飛鏢，鏢的末段常系有紅綠綢布，比普通飛鏢能更快發射。"
SKILL_DETAIL_DESC[9300] = "^ffffff冷卻：90秒\r\r青竹磨尖製成的飛鏢，比普通飛鏢飛得更快。"
SKILL_DETAIL_DESC[9301] = "^ffffff冷卻：90秒\r\r形如蠍刺，淬了弱毒，被擊中者會中毒。"
SKILL_DETAIL_DESC[9302] = "^ffffff冷卻：90秒\r\r三枚金錢鏢連珠發出就是連珠錢鏢。"
SKILL_DETAIL_DESC[9303] = "^ffffff冷卻：90秒\r\r由七枚子鏢組成，發射時連續射出，全中時威力可觀，沒全中時嘛……"
SKILL_DETAIL_DESC[9304] = "^ffffff冷卻：90秒\r\r既然名為“斷魂”，自然是淬了劇毒。被擊中的目標會陷入中毒和散功狀態。"
SKILL_DETAIL_DESC[9305] = "^ffffff冷卻：60秒\r\r有棱角的細長狀堅石，其外型略如蝗蟲。"
SKILL_DETAIL_DESC[9306] = "^ffffff冷卻：60秒\r\r鐵制的念珠，威力比普通飛石更大。"
SKILL_DETAIL_DESC[9307] = "^ffffff冷卻：60秒\r\r像是老人手上把玩的玉珠，比普通飛石能更快發射。"
SKILL_DETAIL_DESC[9308] = "^ffffff冷卻：60秒\r\r將長繩末端系上鐵錘，擲出以傷敵。飛得比普通飛石更快。"
SKILL_DETAIL_DESC[9309] = "^ffffff冷卻：60秒\r\r像是腰掛的玉璧，其實更為沉重，擊中目標後會破除格擋並爆炸。"
SKILL_DETAIL_DESC[9310] = "^ffffff冷卻：60秒\r\r名為刺，卻頗為沉重，擊中目標會破除格擋並使其冰錮。"
SKILL_DETAIL_DESC[9311] = "^ffffff冷卻：60秒\r\r唐門出品的炸彈，威力巨大，擊中目標會爆炸，能破除格擋，使目標眩暈並陷入燃燒狀態。"
SKILL_DETAIL_DESC[9312] = "^ffffff冷卻：150秒\r\r用銅鐵鑄成，筒頂有孔，為裝箭處。筒前開孔，為箭射出處。"
SKILL_DETAIL_DESC[9313] = "^ffffff冷卻：150秒\r\r細長的飛刀，威力比普通飛刀略大。"
SKILL_DETAIL_DESC[9314] = "^ffffff冷卻：150秒\r\r形如蜂刺，能比普通飛刀更快發射。"
SKILL_DETAIL_DESC[9315] = "^ffffff冷卻：150秒\r\r形如棗核，飛行速度比普通飛刀更快。"
SKILL_DETAIL_DESC[9316] = "^ffffff冷卻：150秒\r\r釘上淬了寒毒，被擊中的目標會陷入冰寒狀態。"
SKILL_DETAIL_DESC[9317] = "^ffffff冷卻：150秒\r\r五枚一組的長釘，使用時平射而出，難以躲避。"
SKILL_DETAIL_DESC[9318] = "^ffffff冷卻：150秒\r\r七枚一組，使用時扇形散射而出，能擊中多個目標。"
SKILL_DETAIL_DESC[9319] = "^ffffff冷卻：150秒\r\r薄如柳葉的十餘把飛刀，使用時向周身四面八方散射將目標鈍足，飛刀在穿透目標後還會沿發射路徑返回。"
SKILL_DETAIL_DESC[9320] = "^ffffff冷卻：120秒\r\r普通的縫衣針，當暗器使用需要高超的技巧。"
SKILL_DETAIL_DESC[9321] = "^ffffff冷卻：120秒\r\r五枚在根部相連的鋼針，一次發射就能擊中五處不同位置，威力比普通飛針略大。"
SKILL_DETAIL_DESC[9322] = "^ffffff冷卻：120秒\r\r細如牛毛的飛針，能比普通飛針更快發射。"
SKILL_DETAIL_DESC[9323] = "^ffffff冷卻：120秒\r\r細如蚊須的飛針，飛行速度比普通飛針更快。"
SKILL_DETAIL_DESC[9324] = "^ffffff冷卻：120秒\r\r由六成黃金四成精鋼鑄成，以特殊手法刺入特定穴位可為友軍中量回復氣血值。"
SKILL_DETAIL_DESC[9325] = "^ffffff冷卻：120秒\r\r形似針灸用的金針，以特殊手法刺入特定穴位可為友軍中量回復氣血值並為其解穴。"
SKILL_DETAIL_DESC[9326] = "^ffffff冷卻：120秒\r\r一叢細小的鋼針，以精准的手法向四面射出，能將周身所有目標點穴。"
SKILL_DETAIL_DESC[9327] = "^ffffff冷卻：120秒\r\r一叢鋒銳的鋼針，以重手法向四面射出，專打人腳面，能使周身目標陷入陷足狀態。"
SKILL_DETAIL_DESC[9328] = "^ffffff冷卻：120秒\r\r一叢邪門的毒針，向四面射出，能使周身目標散功。"
SKILL_DETAIL_DESC[9329] = "^ffffff冷卻：120秒\r\r武林中馳名千年的著名暗器！淬了猛烈的寒毒，向四面射出，能使周身目標凍結。"
SKILL_DETAIL_DESC[9330] = "^ffffff冷卻：120秒\r\r日月教長老曲洋的成名暗器，淬了特殊的毒藥，向四面射出，能使周身目標短暫眩暈並大量流血不止。"
SKILL_DETAIL_DESC[9331] = "^ffffff冷卻：180秒\r\r繩索上連著鐵爪，是最簡單也是最常見的飛索類暗器。"
SKILL_DETAIL_DESC[9332] = "^ffffff冷卻：180秒\r\r一枚枚鐵釘，每枚都有四根伸出的鐵刺，長數寸，凡著地必有一刺朝上，踩中的目標會陷入鈍足和流血狀態。"
SKILL_DETAIL_DESC[9333] = "^ffffff冷卻：180秒\r\r形如飛龍，上淬劇毒，被擊中者會中毒並流血不止。"
SKILL_DETAIL_DESC[9334] = "^ffffff冷卻：180秒\r\r由黃金鑄成的昂首吐舌的蛇形，長約二寸八分，蛇信尖端分雙叉，每一叉都是一個倒刺，沉重鋒銳，被擊中者會陷入陷足狀態。"
SKILL_DETAIL_DESC[9335] = "^ffffff冷卻：180秒\r\r這枝小箭正如窮追不捨的舊情人一般讓你如墮冰窟，無處可逃！被擊中的目標會陷入凍結狀態，發射者更可借機利用箭後拉索瞬間移動至目標身邊。"
SKILL_DETAIL_DESC[9336] = "^ffffff冷卻：180秒\r\r一乾一坤的兩個鋼圈，由繩索相連，被擊中的目標會被擊破格擋，並被纏繞。"
SKILL_DETAIL_DESC[9337] = "^ffffff冷卻：180秒\r\r十數枚銀梭齊出，疾如飛燕，避無可避，防無可防。此物一出，身前大範圍的目標全都會被拉回，且進入陷足狀態。"
SKILL_DETAIL_DESC[9338] = "^ffffff冷卻：300秒\r\r奇怪的機關，能射出一朵朵形如金花的暗器。"
SKILL_DETAIL_DESC[9339] = "^ffffff冷卻：300秒\r\r將毒砂裝入筒中發射而出，能比普通機關更快發射。"
SKILL_DETAIL_DESC[9340] = "^ffffff冷卻：300秒\r\r五毒教暗器，乃無數極細的鋼針裝入機括之中，一按即發，威力比普通機關略大。"
SKILL_DETAIL_DESC[9341] = "^ffffff冷卻：300秒\r\r以機關發射鋼針，力道比手更強，能使目標流血不止。"
SKILL_DETAIL_DESC[9342] = "^ffffff冷卻：300秒\r\r唐門的奇特暗器，射出後會突然爆開，在區域內持續傾瀉寒毒，使區域內目標陷入冰寒狀態。"
SKILL_DETAIL_DESC[9343] = "^ffffff冷卻：300秒\r\r在彈丸裡包著無數細如牛毛的梅花針，並且藏有火藥。暗器打出之後，即自行炸裂，不但能傷人，還能使目的地區域持續陷入燃燒狀態。"
SKILL_DETAIL_DESC[9344] = "^ffffff冷卻：300秒\r\r精巧的機關，內含多種補藥，發射後會在目的地區域爆開，為區域內友軍解除不利效果（中毒、流血、燃燒）並中量回復氣血值。"
SKILL_DETAIL_DESC[9345] = "^ffffff冷卻：300秒\r\r著名的奇門暗器，發動機關後會持續發射一段時間，使身前的目標流血不止。"
SKILL_DETAIL_DESC[9346] = "^ffffff冷卻：300秒\r\r此物扁平如匣，長七寸，厚三寸。上用小篆字體雕刻：“出必見血，空回不祥；急中之急，暗器之王”。發動機關後會持續發射一段時間，將身前的目標點穴。"
SKILL_DETAIL_DESC[9382] = "^ffffff客人，我們這裡不允許使用暴力，但是遍地都是水果，你可以……（注意：每次打中目標都會扣血，只有每次將躲藏者擊敗才會回血哦！）"
SKILL_DETAIL_DESC[9383] = "^ffffff知道我們這裡怎麼對付偷椰子的猴嗎，一串溜溜球丟過去，直接雙腳絆蒜動彈不得。後面就不用我教你了吧。"
SKILL_DETAIL_DESC[9384] = "^ffffff躲藏者溜的跟猴一樣，沒關係，讓他嘗嘗我們特製的西瓜汁濃漿吧，保管他腳上灌鉛寸步難移。"
