SKILL_DETAIL_DESC[10304] = "^ffffff    溟鳳臨世飄風起，飛沙走石萬骨枯。相傳獨孤祖師偶然救得一溟鳳，愈後溟鳳不棄且日夜伴其習武。所謂刃出而鳳至，浴血而鳳鳴。一人，一鳳，動若飄風鎮海，靜觀碧海潮生。歷經數十載終悟得此神功。\r    此招以刃攜風，以風助鳳。利刃出鞘之時溟鳳臨世，周遭十米內風捲殘雲，難有僥倖活命者。不過絕招用過後，怒氣平息，怒氣值將歸零。"
SKILL_DETAIL_DESC[10401] = "^ffffff通過不斷的修習，將秘笈裝配至此處後，不僅可以使武學招式產生各式各樣的效果，發揮更大的能力，還可以獲得絕世秘笈中種種不可思議的效果。\r為了避免走火入魔，不同修為的人物，只能裝配一定限制的秘笈。"
SKILL_TIP_REMARK[10401] = "^D7C4A2獨孤獨門心法，呼吸吐納之間能增強招式威力。"
SKILL_DETAIL_DESC[11371] = "^ffffff通過不斷的修習，將秘笈裝配至此處后，不僅可以使武學招式產生各式各樣的效果，發揮更大的能力，還可以獲得絕世秘笈中種種不可思議的效果。\r為了避免走火入魔，不同修為的人物，只能裝配一定限制的秘笈。"
SKILL_TIP_REMARK[11371] = "^D7C4A2玲瓏獨門心法，呼吸吐納之間能增強招式威力。"
