SKILLPACK_TIP_REMARK[4781] = "^D7C4A2般若掌為少林七十二絕技之一，傳為少林達摩祖師所創。般若掌內外皆一，一掌過去內力連綿不絕。曾于剛相刺三豐一役中重傷張三豐。為剛相神僧諸大神功之首。"
SKILLPACK_TIP_REMARK[4782] = "^D7C4A2少林棄武還拳，武器背在背上，以深厚的內力融於兩手，以大量拳法攻擊的招式。"
SKILLPACK_TIP_REMARK[4812] = "^D7C4A2測試輕功招式"
SKILLPACK_TIP_REMARK[4844] = "^D7C4A2天下棍法出少林，掄棍降魔數精英。\r劈紮掃撩動身步，棍影平川似雷霆。\r武林中，向以少林功夫聞名天下，少林棍術在少林功夫中佔有很重要的地位，素有“棍為少林功夫之魁”之說。少林入門棍法是修行少林進階棍法的基礎所在。"
SKILLPACK_TIP_REMARK[4845] = "^D7C4A2普渡棍法為少林七十二絕技之一，少林寺名震天下的獨門棍法，勁力內蓄，外柔內剛，爆發迅猛。"
SKILLPACK_TIP_REMARK[4847] = "^D7C4A2韋陀棍法是少林七十二絕技之一，威猛難當,昔日少林寺高僧玄悲大師之絕技。"
