SKILLPACK_TIP_REMARK[74995] = "^D7C4A2以極其敏捷的身法前沖，揮出致命一劍，這一劍產生的劍氣可擊退對手。"
SKILLPACK_TIP_REMARK[74996] = "^D7C4A2向前大力揮劍威力無比，破綻及小，可擊退敵人。"
SKILLPACK_TIP_REMARK[74997] = "^D7C4A2用快速無比的劍招將敵人挑向半空。"
SKILLPACK_TIP_REMARK[74998] = "^D7C4A2華麗身法移動後，向上撩劍可將敵人打到半空中，有利於追加其他技能。"
SKILLPACK_TIP_REMARK[74999] = "^D7C4A2華山最強劍招之一的紫霞劍法，先將敵人吸到身前，再同全力沖出造成極大傷害。"
SKILLPACK_TIP_REMARK[75163] = "^D7C4A2以優美的身姿劃出波浪般的劍氣，傷敵於無形中。"
SKILLPACK_TIP_REMARK[75164] = "^D7C4A2旋轉借力發出劍氣，造成傷害的同時擊退敵人。"
SKILLPACK_TIP_REMARK[75171] = "^D7C4A2以凜冽的劍氣攻擊敵人。"
SKILLPACK_TIP_REMARK[75172] = "^D7C4A2劍氣如狂風掠過，使敵人站立不穩。"
