WUXUE_DESC1[8921] = "[暫無]"
WUXUE_DESC2[8921] = "[暫無]"
WUXUE_DESC3[8921] = "[暫無]"
WUXUE_DESC1[38094] = "凡人於世，當練得一身好武藝，路見不平，該出手時就出手。有朝一日拜入名門大派後，更當行天下當如猛龍過江，快意恩仇，笑傲江湖。\r絕技特性：看似花拳繡腿，有朝一日也成絕學\r傷害特性：所有招式均為固定傷害"
WUXUE_DESC2[38094] = "天生習得(1級)"
WUXUE_DESC3[38094] = "通用江湖武學\\1.1.0版"
WUXUE_DESC1[38095] = "少林為武學之源，武術博大精深，而棍法為其精髓。少林武功需先修習棍法，既可強身健體，也能提升武藝，獨有的防禦招式使其更適為團隊先鋒。\r絕技特性：團隊坦克，控制療傷\r傷害特性：外功+160%，內功+100%\r元素特性：土"
WUXUE_DESC2[38095] = "加入少林門派(5-10級)"
WUXUE_DESC3[38095] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38096] = "天下劍法出武當，其劍法使用重劍，長四尺三寸，重八斤八兩，揮出時集攻防於一體，練到極致後舉重若輕，配合門派獨有恢復絕技，可謂超凡脫俗。\r絕技特性：內功坦克，護盾反控\r傷害特性：外功+100%，內功+160%\r元素特性：冰"
WUXUE_DESC2[38096] = "加入武當門派(5-10級)"
WUXUE_DESC3[38096] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38097] = "華山武學源起秦漢，劍意取自西嶽華山景致“奇，險”二字，而華山劍法，則取二字其中，融內外功於一體，招式靈動，修習過程既是習武也是修身。\r絕技特性：近戰爆發，快速突進\r傷害特性：外功+160%，內功+100%\r元素特性：主冰輔土"
WUXUE_DESC2[38097] = "加入華山門派(5-10級)"
WUXUE_DESC3[38097] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38098] = "恒山武學負雙劍，善長劍氣禦敵，忍耐力又超乎常人，足可見其門劍意“隱忍”的教誨。恒山推藥法更可用於恢復，因此其與人配合作戰事半功倍。\r絕技特性：遠端劍氣、輔助療傷\r傷害特性：外功+100%，內功+160%\r元素特性：火"
WUXUE_DESC2[38098] = "加入恒山門派(5-10級)"
WUXUE_DESC3[38098] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38099] = "衡山對應二十八宿之軫星，其武學也源自於星空，因此其劍法劍意形人，招式以快速靈活為最大特色，幻影有形，卻可以殺人於無形。\r絕技特性：近戰刺殺，位移反控\r傷害特性：外功+160%，內功+100%\r元素特性：毒"
WUXUE_DESC2[38099] = "加入衡山門派(5-10級)"
WUXUE_DESC3[38099] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38100] = "日月刀法是雙刀為主武器，加上鐵鍊後，雙鏈刀是罪與罰最極致的象徵，所有招式大開大闔，輔以吸血功法續航輔助，在武林中佔有一席之地。\r絕技特性：距離控制，狂戰吸血\r傷害特性：外功+160%，內功+100%\r元素特性：主毒輔火"
WUXUE_DESC2[38100] = "加入日月門派(5-10級)"
WUXUE_DESC3[38100] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38101] = "五仙教，位於苗疆腹地，應運而生的武學以使毒，制蠱為主，由於常與各類武打交到，應運而生的鞭法和爆發團補能力也很強，在江湖獨成一派。\r絕技特性：元素大師，戰術輔助\r傷害特性：外功+100%，內功+160%\r元素特性：冰火毒土"
WUXUE_DESC2[38101] = "加入五仙門派(5-10級)"
WUXUE_DESC3[38101] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38102] = "逍遙派位於西子湖畔，其獨門絕技是將內力化為冰火綿力，附于摺扇攻擊對手，此外也可借舞步為團隊提供恢復，藉此，逍遙派在江湖獨霸一席。\r絕技特性：遠端牽制、戰術逃生\r傷害特性：外功+100%，內功+160%\r元素特性：主冰輔火"
WUXUE_DESC2[38102] = "加入逍遙門派(5-10級)"
WUXUE_DESC3[38102] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38103] = "唐門是江湖秘門，門派中人手持雙槍火炮，射擊精准、快速、密集，一套暗器術更是獨霸江湖，在混戰中常常能十米外快速制敵。\r絕技特性：火槍暗器、戰術迷惑\r傷害特性：外功+160%，內功+100%\r元素特性：主土輔火"
WUXUE_DESC2[38103] = "加入唐門門派(5-10級)"
WUXUE_DESC3[38103] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[38104] = "峨嵋派由先秦宗師司徒玄空所創，此處飛瀑如簾，雲海翻湧，門派中人的內功武藝上乘，在輔助其它同伴戰鬥及提供戰鬥回復時尤其得力。\r絕技特性：內功輔助，團隊療傷\r招式特性：外功+100%，內功+160%\r元素特性：主火輔毒"
WUXUE_DESC2[38104] = "加入峨嵋門派(5-10級)"
WUXUE_DESC3[38104] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[8924] = "普渡棍法為少林七十二絕技之一，勁力內蓄，外柔內剛，為少林武僧必習之藝，易於上手但難於精通，能悟其精髓者寥寥無幾。"
WUXUE_DESC2[8924] = "10級"
WUXUE_DESC3[8924] = "無"
WUXUE_DESC1[8925] = "羅漢拳為少林七十二絕技之一，傳為少林達摩祖師所創。羅漢拳內外皆一，一拳過去內力連綿不絕，為剛相神僧諸大神功之首。"
WUXUE_DESC2[8925] = "20級"
WUXUE_DESC3[8925] = "無"
WUXUE_DESC1[8926] = "韋陀棍法是少林七十二絕技之一，威猛難當，昔日少林高僧玄悲大師絕技。使其棍法者，需念如明鏡心向菩提，方能掌控除妖驅魔之力"
WUXUE_DESC2[8926] = "30級"
WUXUE_DESC3[8926] = "無"
WUXUE_DESC1[10922] = "華山劍法劍意取自華山奇險二字，奇險往往與秀美相映，因此華山劍術奇拔峻秀高遠絕倫，招式處處透著“正合奇勝，險中求勝”的意境。"
WUXUE_DESC2[10922] = "10級"
WUXUE_DESC3[10922] = "無"
WUXUE_DESC1[10923] = "華山的陽剛派劍法，劍劍迅速且有力，劍招所過之處，激起層層氣浪，殺傷力大。"
WUXUE_DESC2[10923] = "20級"
WUXUE_DESC3[10923] = "無"
WUXUE_DESC1[10924] = "[暫無]"
WUXUE_DESC2[10924] = "[暫無]"
WUXUE_DESC3[10924] = "[暫無]"
WUXUE_DESC1[11182] = "五仙教長老齊雲敖之成名絕技，戰鬥時以鞭法的靈動性巧妙制敵，鞭子便宛如靈蛇一般，直鎖對手咽喉，能力強者往往一招取敵性命。"
WUXUE_DESC2[11182] = "10級"
WUXUE_DESC3[11182] = "無"
WUXUE_DESC1[11183] = "五仙教蠱毒秘術，殺人於無形之中，秘術釋放之時，無人敢近身。"
