WUXUE_DESC1[13794] = "武當劍法，以陰柔見長，講究以柔克剛、以靜制動、以簡禦繁、以逸待勞、以小敵大、以弱勝強，其中借力打力四字，尤為精義之所在。"
WUXUE_DESC2[13794] = "10級"
WUXUE_DESC3[13794] = "無"
WUXUE_DESC1[13795] = "融道法於太極劍法中，特色是以“氣”禦“劍”，人劍既可合一，又可分離。"
WUXUE_DESC2[13795] = "20級"
WUXUE_DESC3[13795] = "無"
WUXUE_DESC1[13796] = "逍遙派弟子出神入畫的手法，掌法和擒拿手之中，含蘊有應對劍法、刀法、鞭法、槍法、抓法、斧法等等諸般兵刃的絕招，變法繁複。"
WUXUE_DESC2[13796] = "10級"
WUXUE_DESC3[13796] = "無"
WUXUE_DESC1[13797] = "逍遙派弟子的一項奇特內功，以“無相”兩字為要旨，不著形相，無跡可尋，因此它可以駕馭眾多武林絕技，非內行完全無法看出。"
WUXUE_DESC2[13797] = "20級"
WUXUE_DESC3[13797] = "無"
