WUXUE_DESC1[23162] = "小無相功以“無相”兩字為要旨，不著形相，無跡可尋，與逍遙寒冰術結合後，更多以虛虛實實，似遠似近的內功招式禦敵，入門容易，但易學難精。\r絕技特性：凍體之術，冰盾四擇\r傷害特性：外功+100%，內功+160%\r元素特性：主冰輔火"
WUXUE_DESC2[23162] = "拜入逍遙小無相功宗門後學習(20級)"
WUXUE_DESC3[23162] = "門派專精武學\\1.1.0版"
WUXUE_DESC1[23163] = "天山六陽掌以出神入化的手法，將掌法和擒拿手之中，輔以逍遙摺扇的投擲攻擊，配法高級身法更是靈動無比，修習較難，為高手向武學。\r絕技特性：空中襲擊，摔投點穴\r傷害特性：外功+100%，內功+160%\r元素特性：主冰輔火"
