WUXUE_DESC1[23167] = "漫天花雨為唐門雙槍高階武學，戰鬥以體術和出色的射術與敵人周旋，配合上各種各種暗器，可以在瞬間扭轉戰局，入門容易，但易學難精。\r絕技特性：快速射擊，暗器體術\r傷害特性：外功+160%，內功+100%\r元素特性：主土輔火"
WUXUE_DESC2[23167] = "拜入唐門漫天花雨宗門後學習(20級)"
WUXUE_DESC3[23167] = "門派專精武學\\1.1.0版"
WUXUE_DESC1[23168] = "霹靂雷火為唐門高階武學，將雙槍合併為火炮追求極致攻擊，雖靈活有限，但具有在威力和陣地作戰能力出類拔萃，修習較難，為高手向武學。\r絕技特性：火龍彈藥，移動射擊\r傷害特性：外功+160%，內功+100%\r元素特性：主土輔火"
