WUXUE_DESC1[23172] = "峨嵋滅絕摧心手為至陰道家武學，相傳為黃裳所創，包含無數神奇招式，以爪技和掌法為攻擊手段，尤善近戰攻擊，入門容易，但易學難精。\r絕技特性：爪技點穴，快速連擊\r招式特性：外功+100%，內功+160%\r元素特性：主火輔毒"
WUXUE_DESC2[23172] = "拜入峨嵋滅絕摧心手宗門後學習(20級)"
WUXUE_DESC3[23172] = "門派專精武學\\1.1.0版"
WUXUE_DESC1[23173] = "金頂炎陽掌講究內力至上，以融會貫通為武學至理，使用各種氣功攻擊敵人，近身遠端摔投控場，有相當均衡的表現，修習較難，為高手向武學。\r絕技特性：內功大師，遠程牽制\r招式特性：外功+100%，內功+160%\r元素特性：主火輔毒"
