WUXUE_DESC1[75239] = "江湖上流傳著眾多江湖絕學，這些招式和絕技通常沒有門派限制，但通過巧秒的組合，不僅可以彌補自身弱點，更可將自已的門派特性發揮到極致。\r絕技特性：花拳繡腿，奇宗秘學，彙集於此\r傷害特性：江湖絕學特性不看門派，只論資質"
WUXUE_DESC2[75239] = "江湖絕學研讀修習(60級)"
WUXUE_DESC3[75239] = "通用江湖絕學\\1.1.0版"
WUXUE_DESC1[88441] = "獨孤刀法強調內功修煉，講究嚴密迅捷，不露破綻。其自身隱忍性格修煉出的獨特戰法，更可在瀕死狀態獲得保護，從而瞬間扭轉戰局。\r絕技特性：狀態切換，死亡免疫\r傷害特性：外功+100%，內功+160%\r元素特性：主火輔土"
WUXUE_DESC2[88441] = "加入獨孤門派(5-10級)"
WUXUE_DESC3[88441] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[88442] = "由獨孤九劍演化而來，乃獨孤氏家傳武學。千山劍氣鳥飛絕，扶搖而上撼九天。強調人鷹合一，控炎禦敵；入門容易，但易學難精。\r絕技特性：突進大師，範圍爆發\r招式特性：外功+100%，內功+160%\r元素特性：主火輔土"
WUXUE_DESC2[88442] = "拜入獨孤九溟神功宗門後學習(20-40級)"
WUXUE_DESC3[88442] = "門派專精武學\\1.1.0版"
WUXUE_DESC1[97613] = "誕生于天山派的一門核心武學，經歷門派內部紛爭后部分缺失，遺留至玲瓏弟子手中，如今修煉者只能維持年幼之身，據傳天山童姥的不老之身正是習此而來。\r絕技特性：玲瓏錘法，穩扎穩打\r傷害特性：外功+160%，內功+100%\r元素特性：主土輔火"
WUXUE_DESC2[97613] = "60級自動習得"
WUXUE_DESC3[97613] = "門派大宗武學\\1.1.0版"
WUXUE_DESC1[97614] = "玲瓏弟子雖體態嬌小，但經多年修煉依然氣撼山河，其巨大的武器在其手中能釋放出無窮的能量。\r絕技特性：兇猛剛勁，外功爆發\r傷害特性：外功+160%，內功+100%\r元素特性：主土輔火"
WUXUE_DESC2[97614] = "60級自動習得"
WUXUE_DESC3[97614] = "門派專精武學\\1.1.0版"
WUXUE_DESC1[97615] = "唯我獨尊武學能突破玲瓏弟子的體態限制，招式釋放時根骨血脈被注滿能量，變為女武神形態，輕盈靈動。\r絕技特性：輕盈靈動，節奏大師\r傷害特性：外功+160%，內功+100%\r元素特性：主土輔火"
WUXUE_DESC2[97615] = "60級自動習得"
WUXUE_DESC3[97615] = "門派專精武學\\1.1.0版"
