SKILL_DETAIL_DESC_EX[163] = "舞棍如流星般遮蔽全身，攻擊身旁的所有敵人。此絕技可^00ff00在移動中施放^ffffff，且移動中會獲得^00ff00俊足^ffffff效果，無視移動限制效果影響。"
SKILL_DETAIL_DESC_EX[4827] = "以蒼龍攪海之勢向前滾翻，將路徑上的所有目標^e76041吸附^ffffff向前移動，最終一記^00ff00剛體^ffffff重砸，將露出弱點的目標^e76041擊倒^ffffff。此絕技可以^00ff00在空中使用^ffffff，且移動中會獲得^00ff00俊足^ffffff效果，無視移動限制效果影響。"
SKILL_DETAIL_DESC_EX[4828] = "將目標用棍挑起後連刺數次，然後轉身一棍將敵人^e76041擊飛^ffffff。此絕技為^00ff00抓取判定^ffffff。"
SKILL_DETAIL_DESC_EX[989] = "長棍散開為三節棍，伸長攻擊直線上的目標，將其全部^e76041點穴^ffffff。"
SKILL_DETAIL_DESC_EX[6003] = "一記勢大力沉的橫掃，推開面前的所有敵人，並打得他們骨軟筋麻，使之在短時間內被^e76041陷足^ffffff。"
SKILL_DETAIL_DESC_EX[5997] = "旋轉投擲出手中長棍，將前方敵人^e76041推往遠處並聚在一起^ffffff，隨即在遠方形成一個旋風區域，旋風會將附近敵人^e76041吸附^ffffff在周圍。"
SKILL_DETAIL_DESC_EX[4829] = "以剛猛無儔的羅漢拳法進行攻擊，對敵造成傷害。合招時全身^00ff00剛體^ffffff。"
SKILL_DETAIL_DESC_EX[4839] = "以剛猛無儔的羅漢拳法進行攻擊，對敵造成傷害。合招時全身^00ff00剛體^ffffff。"
SKILL_DETAIL_DESC_EX[2033] = "以剛猛無儔的羅漢拳法進行攻擊，對敵造成傷害。合招時全身^00ff00剛體^ffffff。"
SKILL_DETAIL_DESC_EX[2034] = "以剛猛無儔的羅漢拳法進行攻擊，對敵造成傷害。合招時全身^00ff00剛體^ffffff。"
SKILL_DETAIL_DESC_EX[968] = "以左右勾的重拳進行攻擊，對前方敵人造成較高傷害。"
SKILL_DETAIL_DESC_EX[969] = "以左右勾的重拳進行攻擊，對前方敵人造成較高傷害。"
SKILL_DETAIL_DESC_EX[4834] = "向前方推出一道劈空掌力，^e76041擊退^ffffff其遇到的第一個目標，蓄力時間越長威力越大。蓄力滿後會以全身震地並釋放出巨型真氣波浪，可以^e76041眩暈^ffffff並^e76041穿透^ffffff多個目標。"
SKILL_DETAIL_DESC_EX[2035] = "足下生風，突進至目標身邊，以沖拳進行攻擊，使擊中的目標陷入^e76041鈍足^ffffff狀態。此絕技可^00ff00在空中使用^ffffff。"
SKILL_DETAIL_DESC_EX[4831] = "用快速的掌法攻擊前方敵人，使擊中的目標有一定幾率陷入^e76041陷足^ffffff狀態，施放過程中連按技能鍵可以增加攻擊次數，如果全部擊完，可以追加一記重拳將目標^e76041擊退^ffffff。"
SKILL_DETAIL_DESC_EX[4832] = "以^00ff00連環^ffffff快腿向前方踢擊五次，並將擊中的目標^e76041吸附^ffffff一起移動，最後附加一記迴旋踢將之推開。此絕技可^00ff00在空中使用^ffffff，且施放過程會獲得^00ff00俊足^ffffff效果，無視移動限制效果影響。"
SKILL_DETAIL_DESC_EX[6103] = "雙掌砸地，勢如山崩，對周身區域內的所有目標造成傷害，使之^e76041鈍足^ffffff，並將露出弱點的目標^e76041擊倒^ffffff。蓄力時間越長，傷害範圍和威力越大，^e76041鈍足^ffffff持續時間也越長，若蓄滿則會引發大範圍土地翻騰，造成持續傷害。"
SKILL_DETAIL_DESC_EX[6138] = "小幅前沖後踢出一記撩陰腿，使擊中的目標陷入^e76041鈍足^ffffff狀態。一段時間內可以重複使用該絕技，最多追加兩段攻擊，每次攻擊都會將露出弱點的目標^e76041擊倒^ffffff。"
SKILL_DETAIL_DESC_EX[975] = "如鐵索橫江的氣勢，以掃堂腿攻擊身前大範圍敵人的下盤，將露出弱點的目標^e76041擊倒^ffffff。"
SKILL_DETAIL_DESC_EX[4833] = "挾泰山以超北海，用肩部對前方進行勢不可擋的撞擊，將路徑上的所有敵人^e76041擊飛^ffffff並^e76041鈍足^ffffff，撞擊過程中會獲得^00ff00俊足^ffffff效果，無視移動限制效果影響。"
SKILL_DETAIL_DESC_EX[6016] = "睡夢羅漢拳中最著名的一招，躍起後以睡夢羅漢之姿向下砸地，對區域內的所有目標造成傷害，使之^e76041鈍足^ffffff，並將露出弱點的目標^e76041擊倒^ffffff。此絕技可以^00ff00在空中使用^ffffff，且^00ff00在空中使用^ffffff時能造成額外傷害。"
SKILL_DETAIL_DESC_EX[4554] = "向前方進行快速的斬擊，對目標造成傷害。"
SKILL_DETAIL_DESC_EX[5409] = "向前方進行快速的斬擊，對目標造成傷害。"
SKILL_DETAIL_DESC_EX[4555] = "掄起長劍繞身兩周橫斬，對自身周圍的多個目標造成傷害。"
SKILL_DETAIL_DESC_EX[4556] = "氣沉丹田，為自身^00ff00增加冰系傷害^ffffff。"
SKILL_DETAIL_DESC_EX[4557] = "以真元之力護體，為周圍單位以一定量^00ff00回復氣血值^ffffff，同時釋放後自身獲得護體狀態，^00ff00增加內功防禦力^ffffff。在護體狀態下，如受到敵人攻擊，則獲得凝神效果。凝神效果會按疊加層數成倍提升真元護體類絕技的回復效果。"
SKILL_DETAIL_DESC_EX[8464] = "轉身橫掄向身前砍出一道劍氣，對前方直線範圍內的目標造成傷害。"
