SKILL_DETAIL_DESC_EX[4684] = "掃出一道月牙劍氣，可使目標陷入^e76041燃燒^ffffff狀態，且在未觸發^00ff00當身^ffffff的情況下，絕技冷卻時間為15秒。出招時若蓄力則可保持^00ff00當身^ffffff狀態，若受到攻擊，則會瞬間突進至目標身後將其^e76041點穴^ffffff。\r觸發^00ff00當身^ffffff後自身會在短時內獲得^00ff00連環^ffffff效果，但本絕技自身不受^00ff00連環^ffffff效果影響。"
SKILL_DETAIL_DESC_EX[4686] = "推出一道突刺劍氣，可使目標陷入^e76041鈍足^ffffff狀態，且在未觸發^00ff00當身^ffffff的情況下，絕技冷卻時間為12秒。出招時若蓄力則可保持^00ff00當身^ffffff狀態，若受到攻擊，則會瞬間跳至目標前方空中對敵發動^00ff00連環^ffffff刺擊，使目標^e76041鈍足^ffffff並^e76041散功^ffffff。\r觸發^00ff00當身^ffffff後自身會在短時內獲得^00ff00連環^ffffff效果，當^00ff00連環^ffffff效果存在時，本絕技將略過正常出招段，直接全身^00ff00剛體^ffffff以反擊段進行攻擊。\r若已經處於^00ff00連環^ffffff狀態下，也會再次觸發^00ff00連環^ffffff效果。"
SKILL_DETAIL_DESC_EX[4689] = "跪地前刺敵人，將露出弱點的目標^e76041擊飛^ffffff，且在未觸發^00ff00當身^ffffff的情況下，絕技冷卻時間為12秒。出招時若蓄力則可保持^00ff00當身^ffffff狀態，若受到攻擊則會立刻^00ff00剛體^ffffff臥地刺擊將目標^e76041擊倒^ffffff，使其^e76041鈍足^ffffff且^e76041流血^ffffff不止，再以迴旋腿進行追擊。\r觸發^00ff00當身^ffffff後自身會在短時內獲得^00ff00連環^ffffff效果，當^00ff00連環^ffffff效果存在時，本絕技將略過正常出招段，直接全身^00ff00剛體^ffffff以反擊段進行攻擊。\r若已經處於^00ff00連環^ffffff狀態下，也會再次觸發^00ff00連環^ffffff效果。"
SKILL_DETAIL_DESC_EX[8586] = "向前方突進，對敵人造成傷害並使其陷入^e76041燃燒^ffffff狀態，且在未觸發^00ff00當身^ffffff的情況下，絕技冷卻時間為18秒。出招時若蓄力則可保持^00ff00當身^ffffff狀態，若受到攻擊，則會向前後分別發射劍氣，將沿途所有敵人^e76041陷足^ffffff並^e76041擊飛^ffffff。\r觸發^00ff00當身^ffffff後自身會在短時內獲得^00ff00連環^ffffff效果，當^00ff00連環^ffffff效果存在時，本絕技將略過正常出招段，直接全身^00ff00剛體^ffffff以反擊段進行攻擊。\r若已經處於^00ff00連環^ffffff狀態下，也會再次觸發^00ff00連環^ffffff效果。"
