SKILL_DETAIL_DESC_EX[8950] = "通過蓄力對周圍造成寒冰的效果。該招式隨著蓄力時間長短有不同的效果：\r一段蓄力，在自身周圍凝結一片極寒領域，瞬間對敵人造成至少3層^e76041冰寒^ffffff效果；\r二段蓄力，對周圍造成^e76041冰寒^ffffff效果，再施放大量冰柱對周圍造成^e76041冰錮^ffffff效果；\r三段蓄力，對周圍造成^e76041冰寒^ffffff效果，用冰柱對周圍造成短暫^e76041冰錮^ffffff效果，最後將冰柱機爆將附近所有敵人^e76041凍結^ffffff。"
