SKILL_DETAIL_DESC_EX[8952] = "向前方打出一計勾拳，在目標周圍產生巨大的龍拳風，龍拳風持續過程中會將敵人^e76041吸附^ffffff在周圍。"
SKILL_DETAIL_DESC_EX[8953] = "用高速拳法攻擊身前目標，一定幾率使受傷的敵人^e76041陷足^ffffff，施放過程中連按技能鍵可以增加攻擊次數。左右手交替攻擊十十次後會進行雙手重刺，將所有目標^e76041擊退^ffffff並使其^e76041流血^ffffff。"
SKILL_DETAIL_DESC_EX[8954] = "回轉一圈，用內力推開周圍單位並對其^e76041破除格擋^ffffff。然後用指勁劃出一道氣波，將前方的敵人全部^e76041點穴^ffffff。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8955] = "向前方放出去巨大的氣功波，使受傷的敵人陷入^e76041冰錮^ffffff狀態。該絕技可以蓄力相當長的時間，蓄力後放出的氣功波會越來越大，效果隨之越來越強。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8956] = "以蠱敵之術攻擊周圍單位，使敵人陷入^e76041鈍足^ffffff狀態。同時會借力向前方扔出一排生死符，使擊中的單位^e76041擊退^ffffff，並受到強烈的^e76041中毒^ffffff效果影響並進入走火入魔狀態。"
SKILL_DETAIL_DESC_EX[8957] = "以幻影移的身形位移至目標身前，突進除了可以破除防禦，還可將目標擊暈。\r此絕技可以^00ff00在空中使用^ffffff。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8958] = "一躍而起跳至目的地區域，對附近的單位中量^00ff00回復氣血值^ffffff，並丟出一個可持續獲得^00ff00俊足^ffffff效果的法陣\r此絕技可以^00ff00在空中使用^ffffff。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8959] = "向前方快速推出以快速幻影攻擊周圍目標使其^e76041散功^ffffff，神掌將不斷^e76041吸附^ffffff周圍的目標向前方飛行。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8960] = "消耗自身大量內力，為目標或自身極大量^00ff00回復氣血值^ffffff，且回復大量體力。\r絕技過程全身^00ff00剛體^ffffff且^00ff00極大減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8961] = "將內力貫入雙手在地面猛劃，^e76041吸附^ffffff周圍所有單位並使其陷入^e76041燃燒^ffffff和險足狀態，並附加內力流失效果。\r絕技過程全身^00ff00剛體^ffffff且^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8962] = "快速對足下踩踏，使附近所有單位陷入^e76041鈍足^ffffff狀態。在短暫的延時後，足下會產生猛烈的爆炸，將附近所有單位^e76041擊飛^ffffff。\r絕技過程全身^00ff00剛體^ffffff且^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8963] = "邊移動邊進行高速的旋轉，將敵人^e76041吸附^ffffff在周圍並持續造成^e76041燃燒^ffffff狀態。旋轉的同時會不斷向周圍發射聖火令，聖火令擊中的敵人會被^e76041陷足^ffffff效果影響。\r絕技過程全身^00ff00剛體^ffffff且^00ff00大量減免受到的傷害^ffffff，且移動中會獲得^00ff00俊足^ffffff效果，無視移動限制效果影響。"
SKILL_DETAIL_DESC_EX[8964] = "聚集全身力氣，以幻影攻擊前方直線上的敵人，使前方敵人^e76041陷足^ffffff後，並使所有受影響的目標受到^e76041破除格擋^ffffff、^e76041鈍足^ffffff、^e76041目盲^ffffff、^e76041散功^ffffff效果影響，幻影飛回時還將使所有敵人進入^e76041點穴^ffffff狀態。\r絕技過程全身^00ff00剛體^ffffff且^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8965] = "快速突進到目標附近，用高速攻擊的拳法使對方無法動彈，並召出巨龍使敵人陷入^e76041封穴^ffffff狀態。在攻擊數次後，將周圍所有目標^e76041擊飛^ffffff。\r此絕技可以^00ff00在空中使用^ffffff。\r絕技過程全身^00ff00霸體^ffffff且^00ff00極大減免受到的傷害^ffffff。因招式傷害巨大，擊中選中對手後將會隨機選取周圍單個目標進行攻擊。"
SKILL_DETAIL_DESC_EX[8966] = "運功牽引目標，對其造成傷害並陷入^e76041力竭^ffffff狀態，並在短暫的準備後，以神乎奇技的動作，將目標拉近至自身的位置，並在自身周圍發動爆炸使敵人^e76041散功^ffffff，同時自身^00ff00互換^ffffff到目標位置，並將目標原來所處位置周圍的敵人^e76041擊飛^ffffff。\r絕技過程全身^00ff00霸體^ffffff且^00ff00極大減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8967] = "用內力將周圍所有敵人逐漸吸往身邊：\r第一段：將前方遠處的扇形範圍敵人^e76041吸附^ffffff過來；\r第二段，將左右兩邊範圍內的敵人^e76041吸附^ffffff過來；\r第三段，將自身周圍的所有敵人^e76041吸附^ffffff過來。\r吸到的敵人全程處於^e76041散功^ffffff狀態，完成後，將自身吸入的內力引爆，對周圍造成極大傷害並將所有單位^e76041擊退^ffffff。\r絕技過程全身^00ff00霸體^ffffff且^00ff00極大減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[8968] = "扔出無數絲帶，其中夾雜無數銀針，使等周圍的敵人陷入^e76041封穴^ffffff狀態。稍等片刻，將以鬼魅般的身法在自身周圍快速來回穿梭攻擊，受傷的目標將陷入^e76041流血^ffffff狀態。\r絕技過程全身^00ff00霸體^ffffff且^00ff00極大減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[9108] = "該絕技可以短期內連按施放三次。\r第一、二次：足下生風，向目標方向快速位移，使所有延途的敵人陷入^e76041封穴^ffffff狀態。\r第三次，用內力引爆前方的地面，所有受傷的單位陷入^e76041鈍足^ffffff、^e76041陷足^ffffff、^e76041封穴^ffffff狀態。\r此絕技可以^00ff00在空中使用^ffffff。\r絕技過程全身^00ff00霸體^ffffff且^00ff00極大減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[10187] = "凝聚全身內勁，向目標踢出一個能量球波，使被擊中單位陷入^e76041散功^ffffff狀態。\r蓄力滿後可踢出一個巨大的真氣球波，使所有延途的敵人陷入^e76041點穴^ffffff狀態。出招時蓄力則可保持^00ff00當身^ffffff狀態，若受到攻擊，則會立即踢擊目標背部使其^e76041眩暈^ffffff，同時未蓄滿的能量波會自動慢速追擊目標，並造成^e76041陷足^ffffff效果。"
SKILL_DETAIL_DESC_EX[10280] = "快速揮砍目標並用匕首刺擊，對敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10281] = "快速揮砍目標並用匕首刺擊，對敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10282] = "轉身盡力將腿劈下重砸目標，並擊出踏空氣浪，可對身前和空中敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10283] = "可以在兩種形態間切換戰鬥狀態。暴風可提升自身^00ff00內功攻擊^ffffff，剛毅可提升自身^00ff00內外功防禦^ffffff，同時使攻擊可以一定量的^00ff00吸取氣血值^ffffff。"
SKILL_DETAIL_DESC_EX[10284] = "翻身力劈，以斬日之勢，將身前直線目標^e76041擊倒^ffffff。"
SKILL_DETAIL_DESC_EX[10285] = "天下武學實乃一家，昔日令狐沖小露一式凰羽遮月，孤獨融匯貫通學為己用，可朝目標快速突進刺擊,使敵人陷入^e76041陷足^ffffff狀態，並附帶短暫^e76041擊暈^ffffff效果。"
SKILL_DETAIL_DESC_EX[10286] = "獨孤宗族歷來內力渾厚，擅長將內勁聚集丹田，以獲得^00ff00免傷之氣^ffffff。狀態加上後更可向周身奮力揮出一周，將周圍目標^e76041擊暈^ffffff。同時可恢復較多氣血值。"
SKILL_DETAIL_DESC_EX[10287] = "向前方發出快速飛行的鷹狀劍氣，對直線上的敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10288] = "向前方發出快速飛行的鷹狀劍氣，對直線上的敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10289] = "向前方發出快速飛行的鷹狀劍氣，對直線上的敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10290] = "向前方發出快速飛行的鷹狀劍氣，對直線上的敵人造成傷害。"
SKILL_DETAIL_DESC_EX[10291] = "以破浪之勢側翻到目標身後對其進行劈擊攻擊，之後挑空一擊將其^e76041擊飛^ffffff。此絕技可^00ff00在空中使用^ffffff。"
SKILL_DETAIL_DESC_EX[10293] = "快速揮出劍氣朝前方扇形區域刺擊，第一下可將靠近身邊的目標^e76041推開^ffffff，第二下可將目標直接^e76041擊倒^ffffff。"
SKILL_DETAIL_DESC_EX[10299] = "愛鷹俯身落下與人合力發起旋風攻擊，所經之處的目標將會被^e76041吸附^ffffff到身邊。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10292] = "朝身前打出一深一淺的雙重旋風攻擊。淺色旋風可在原處造成持續^e76041吸附^ffffff傷害，深色旋風會將所經之處目標^e76041擊飛^ffffff。人物攻擊的瞬間還可將頭頂的空中目標直接^e76041擊飛^ffffff。"
SKILL_DETAIL_DESC_EX[10296] = "禦使愛鷹疾速升空，可將身邊敵人推開數米。然後自身朝目的地區域快速撞擊，同時愛鷹召喚巨大鳥爪砸擊敵人，可造成^e76041流血^ffffff和^e76041擊暈^ffffff傷害。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10303] = "向目標發射一枚逐漸加速的鳳凰烈焰，可將所過之處的目標推開，烈焰波可對選中的敵人進行跟蹤追擊並飛行一定距離，同時造成^e76041點燃^ffffff效果。"
SKILL_DETAIL_DESC_EX[10298] = "縱身躍起借助鷹爪之勢朝所選區域進行鏟擊，落地後更可滑行數米，將敵人^e76041聚集^ffffff一處並^e76041陷足^ffffff。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10297] = "吹起號角禦使愛鷹召喚幼鳥朝目標發起數波撞擊，第二下可將身前目標推開數米同時附帶^e76041鈍足^ffffff，第三下更可將敵人直接^e76041擊飛^ffffff。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10294] = "禦使愛鷹疾速前沖貫擊，可對多個目標造成^e76041點穴^ffffff傷害。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10295] = "愛鷹將目標牢牢^e76041抓取^ffffff空中，同時人物向其展開多段幻影強攻，最後一擊更可將目標^e76041踢飛^ffffff。此絕技為^00ff00抓取判定^ffffff。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10300] = "連續兩次的近戰刺擊，同時愛鷹在空中蓄起神凰之力，蓄滿後朝身前區域發起焚炎強攻，可將敵人^e76041擊倒^ffffff。第一下人物攻擊可^e76041破除格擋^ffffff並將敵人^e76041散功^ffffff。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10301] = "鳳凰涅槃，永生不敗。將愛鷹化身的烈焰精華吸收到左拳之上，然後躍起朝目的地區域打出祝融之炎，可將敵人^e76041擊倒^ffffff並造成^e76041點燃^ffffff和^e76041陷足^ffffff效果。出招時全身^00ff00剛體^ffffff。^1EFF00使用該絕技需裝備20級以上含鷹武器^ffffff。"
SKILL_DETAIL_DESC_EX[10796] = "上挑目標，再向周圍大範圍斬擊，同時發出一道可將目標^e76041擊飛^ffffff的地裂波。第一擊可擊落空中目標並使其^e76041目盲^ffffff，第二擊可造成^e76041鈍足^ffffff效果。"
SKILL_DETAIL_DESC_EX[10797] = "凝聚全身內力向周身發出金色氣震攻擊，可將敵人^e76041吸附^ffffff到身邊造成巨大傷害，並附帶^e76041陷足^ffffff效果。"

SKILL_DETAIL_DESC_EX[10861] = "消耗兩百點怒氣朝前方射出大量冰矢，將擊中目標^e76041冰錮^ffffff，最後一擊更可將對手^e76041凍結^ffffff。此絕技^e76041必須在空中使用^ffffff，但出招時全身^00ff00剛體^ffffff。可獲得較多冰屬性傷害加成。"
SKILL_DETAIL_DESC_EX[10862] = "消耗兩百點怒氣朝前方射出大量火焰彈，並附帶^e76041點燃^ffffff效果,同時使目標陷入極長時間的^e76041散功^ffffff狀態。此絕技^e76041必須在空中使用^ffffff，但出招時全身^00ff00剛體^ffffff。可獲得較多火屬性傷害加成。"
SKILL_DETAIL_DESC_EX[10863] = "消耗兩百點怒氣召喚出戰神巨斧朝前方連續揮擊，可對目標造成^e76041中毒^ffffff效果並連續擊暈，最後一擊更可將目標直接擊倒。此絕技^e76041必須在空中使用^ffffff，但出招時全身^00ff00剛體^ffffff。可獲得較多毒屬性傷害加成。"
SKILL_DETAIL_DESC_EX[10864] = "消耗兩百點怒氣召喚出巨大銅鐘捶擊地面，可將周身敵人^e76041擊倒^ffffff並造成巨大傷害。此絕技^e76041必須在空中使用^ffffff，但出招時全身^00ff00剛體^ffffff。可獲得較多土屬性傷害加成。"
SKILL_DETAIL_DESC_EX[10865] = "消耗兩百點怒氣召喚出數道閃電，將周身敵人^e76041擊暈^ffffff數秒。此絕技^e76041必須在空中使用^ffffff，但出招時全身^00ff00剛體^ffffff。"
SKILL_DETAIL_DESC_EX[10910] = "朝前方射出五個不同方向的月牙波。"
SKILL_DETAIL_DESC_EX[10911] = "凝聚全身內勁，向目標踢出一個能量球波，使被擊中單位陷入^e76041散功^ffffff狀態。\r蓄力滿後可踢出一個巨大的真氣球波，使所有延途的敵人陷入^e76041點穴^ffffff狀態。出招時蓄力則可保持^00ff00當身^ffffff狀態，若受到攻擊，則會立即踢擊目標背部使其^e76041眩暈^ffffff，同時未蓄滿的能量波會自動慢速追擊目標，並造成^e76041陷足^ffffff效果。"
SKILL_DETAIL_DESC_EX[10912] = "丟出1個火焰陷阱，持續對周圍目標造成^e76041點燃^ffffff和^e76041吸附^ffffff效果。"
SKILL_DETAIL_DESC_EX[10913] = "強制讓目標和自身對攻（對S級絕學無效），戰斗中雙方均無敵，結束時用戰力比^e76041互相造成傷害^ffffff。戰力比受^e76041寶石價值、陣石價值、武魂覺醒等級、部分裝備強化經驗^ffffff影響。戰斗傷害和具體數值無關，直接受戰力比影響按雙方總氣血的^00ff00百分比^ffffff進行扣血。觸發對攻后，被攻擊方可獲得數分鐘免疫效果。"
SKILL_DETAIL_DESC_EX[10915] = "疾速朝目標衝鋒，並將其擊暈，^00ff00每殺死5名玩家啟動絕技^ffffff。"
SKILL_DETAIL_DESC_EX[10916] = "向目標發射三枚逐漸加速的火焰彈,可追蹤目標，並將其^e76041擊退^ffffff，^00ff00每殺死5名玩家啟動絕技^ffffff。"
SKILL_DETAIL_DESC_EX[10917] = "契血之印可10秒內提升玩家少量內外功攻擊和一定量的內外功防禦，^00ff00每殺死5名玩家自動施放^ffffff。"
SKILL_DETAIL_DESC_EX[10918] = "通筋之道可單次回復玩家一定量氣血值，^00ff00每殺死5名玩家自動施放^ffffff。"
SKILL_DETAIL_DESC_EX[10919] = "疾風之魂可單次回復玩家大量體力值，^00ff00每殺死5名玩家自動施放^ffffff。"
SKILL_DETAIL_DESC_EX[10920] = "妙音術可持續回復玩家大量氣血值，^00ff00氣血低於50%自動施放^ffffff。"
SKILL_DETAIL_DESC_EX[10921] = "純陽術可單次回復玩家較多氣血值，^00ff00氣血低於50%自動施放^ffffff。"
SKILL_DETAIL_DESC_EX[10922] = "背水術在4秒內提升玩家一定量的內外功攻擊，^00ff00氣血低於50%自動施放^ffffff。"
SKILL_DETAIL_DESC_EX[10923] = "穩固術讓玩家1.5秒內減免大量所受的攻擊傷害，^00ff00氣血低於50%自動施放^ffffff。"
