SKILL_DETAIL_DESC_EX[11344] = "招式分兩種形態。^00ff00玲瓏形態^ffffff：揮舞手中的巨錘向前方發射氣浪，可以在中距離對敵人造成傷害。^00ff00玲瓏武神形態^ffffff：向前方進行錘擊，可以傷害前方的的敵人，造成較高傷害，第四式傷害范圍較大。"
