SKILL_DETAIL_DESC_EX[11349] = "近身使用的普通二段攻擊。"
SKILL_DETAIL_DESC_EX[11350] = "橫揮巨錘一周，對范圍內的敵人造成傷害并將目標^e76041擊退^ffffff。"
SKILL_DETAIL_DESC_EX[11351] = "玲瓏秘術，為自身^00ff00增加土系傷害^ffffff。"
SKILL_DETAIL_DESC_EX[11352] = "向前方快速突進沖鋒，命中目標后會將目標^e76041點穴^ffffff。"
SKILL_DETAIL_DESC_EX[11353] = "使用全身的力量將錘子向前方擲出，對前方直線范圍造成傷害,并將沿途的敵人^e76041擊退^ffffff。"
SKILL_DETAIL_DESC_EX[11354] = "奮力躍起，向周圍范圍內的敵人進行全方位砸擊，釋放過程中連按技能鍵會增加錘擊的次數，連打完成后會多追加一段強力錘擊。"
SKILL_DETAIL_DESC_EX[11335] = "躍入空中，將錘子高高舉起，向前方區域猛砸數次，造成大量傷害，最后一段錘擊會對命中的敵人造成^e76041擊倒^ffffff效果。"
SKILL_DETAIL_DESC_EX[11336] = "絕技分兩種形態。^00ff00玲瓏形態^ffffff：蓄力揮舞巨錘，隨著蓄力時間的增加攻擊范圍和傷害都會增加。蓄力滿后會將敵人^e76041擊飛^ffffff。^00ff00玲瓏武神形態^ffffff：迅速用巨錘對前方范圍內敵人進行揮擊，使目標^e76041眩暈^ffffff，該過程出招時全身^00ff00剛體^ffffff。\r（只需將^00ff00混沌一破^ffffff和^00ff00乾坤一擊^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）"
SKILL_DETAIL_DESC_EX[11337] = "跳上巨錘，使其連續對地面造成砸擊，對命中的敵人造成短時間^e76041散功^ffffff效果。"
SKILL_DETAIL_DESC_EX[11338] = "絕技分兩種形態。^00ff00玲瓏形態^ffffff：在移動中掄起巨錘，對周圍360度的敵人造成持續旋轉打擊，有小范圍的^e76041吸附^ffffff效果。^00ff00玲瓏武神形態^ffffff：在原地進行高速旋轉，會^e76041吸附^ffffff近距離敵人并對其造成傷害。旋轉的同時會不斷向周圍發射流星錘，流星錘擊中的敵人會被^e76041擊退^ffffff。\r（只需將^00ff00嘯風卷地^ffffff和^00ff00星亂紫煙^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）"                                                    
SKILL_DETAIL_DESC_EX[11339] = "全身^00ff00剛體^ffffff的強力三連擊，將目標^e76041擊退^ffffff。"
SKILL_DETAIL_DESC_EX[11340] = "絕技分兩種形態。^00ff00玲瓏形態^ffffff：跳起用雙腳全力將巨錘向前方踢出，巨錘的旋轉氣流會對敵人造成^e76041吸附^ffffff效果，巨錘到達最遠處會對附近的敵人造成^e76041頓足^ffffff效果。^00ff00玲瓏武神形態^ffffff：將巨錘向前方扔出，被碰撞的敵人將會^e76041陷足^ffffff。緊接著向前方進行突進，對目標造成大量傷害并將目標^e76041擊退^ffffff。\r（只需將^00ff00長風萬里^ffffff和^00ff00雁過玉門^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）"
SKILL_DETAIL_DESC_EX[11341] = "絕技分兩種形態。^00ff00玲瓏形態^ffffff：鎖定目標位置，在目標頭頂召喚一個巨大的流星錘垂直落下撞擊，蓄力會增大流星錘的撞擊范圍，蓄力滿會追加一個^e76041擊倒^ffffff效果。^00ff00玲瓏武神形態^ffffff：在目標范圍內召喚大量小流星錘進行砸擊，造成大量傷害并將目標短時間^e76041擊暈^ffffff。\r（只需將^00ff00珠落玉盤^ffffff和^00ff00萬樹花開^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）"
SKILL_DETAIL_DESC_EX[11342] = "向前方噴射扇形的高溫氣浪，對大范圍內的敵人造成多段打擊。\r（只需將兩種形態對應的其中一個技能裝配到技能欄,不同形態時技能會自動切換）"
SKILL_DETAIL_DESC_EX[11343] = "絕技分兩種形態。^00ff00玲瓏形態^ffffff：借錘身上跳到高空，向下用雙手發出強大氣浪，對近身的敵人造成多段傷害，最終落地爆炸對敵人造成^e76041擊倒^ffffff效果。^00ff00玲瓏武神形態^ffffff：用巨錘將敵人擊飛后進行轟擊再重重砸到地上。此絕技為^00ff00抓取判定^ffffff。\r（只需將^00ff00一點靈珠^ffffff和^00ff00天花亂墜^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）"

