SKILL_DETAIL_DESC_EX[11362] = "释放玲珑之力，变身为^00ff00玲珑武神^ffffff。短时间内可多次穿梭至目标位置并用腿部进行砸击,将目标^e76041散功^ffffff。此绝技可^00ff00在空中使用^ffffff。"
SKILL_DETAIL_DESC_EX[11363] = "絕技分兩種形態。^00ff00玲瓏形態^ffffff：鎖定目標位置，在目標頭頂召喚一個巨大的流星錘垂直落下撞擊，蓄力會增大流星錘的撞擊范圍，蓄力滿會追加一個^e76041擊倒^ffffff效果。^00ff00玲瓏武神形態^ffffff：在目標范圍內召喚大量小流星錘進行砸擊，造成大量傷害并將目標短時間^e76041擊暈^ffffff。\r（只需將^00ff00珠落玉盤^ffffff和^00ff00萬樹花開^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）。"
SKILL_DETAIL_DESC_EX[11364] = "絕技分兩種形態。^00ff00^00ff00玲瓏形態^ffffff^ffffff：跳起用雙腳全力將巨錘踢出，巨錘的旋轉氣流會對敵人造成^e76041吸附^ffffff效果，巨錘到達最遠處會對附近的敵人造成^e76041頓足^ffffff效果。^00ff00玲瓏武神形態^ffffff：將巨錘向前方扔出，被碰撞的敵人將會^e76041陷足^ffffff。緊接著向前方進行突進，對目標造成大量傷害并將目標^e76041擊退^ffffff。\r（只需將^00ff00長風萬里^ffffff和^00ff00雁過玉門^ffffff的其中一個裝配到技能欄,不同形態時技能會自動切換）"
SKILL_DETAIL_DESC_EX[11365] = "釋放玲瓏之力，變身為^00ff00玲瓏武神^ffffff，并向前方踢出玲瓏心，將沿途碰撞的敵人^e76041點穴^ffffff。"

SKILL_DETAIL_DESC_EX[11479] = "向前方快速推出以快速幻影攻擊周圍目標使其^e76041散功^ffffff，神掌將不斷^e76041吸附^ffffff周圍的目標向前方飛行。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[11483] = "抓住前方敵人的衣襟，并猛力一擊將摔投，并將其重重^e76041擊退^ffffff一段距離，并附加十八跌效果，2秒后使目標跌倒。\r此絕技為^00ff00抓取判定^ffffff。"
SKILL_DETAIL_DESC_EX[11484] = "邊移動邊進行高速的旋轉，將敵人^e76041吸附^ffffff在周圍并持續造成^e76041燃燒^ffffff狀態。旋轉的同時會不斷向周圍發射圣火令，圣火令擊中的敵人會被^e76041陷足^ffffff效果影響。\r絕技過程全身^00ff00剛體^ffffff且^00ff00大量減免受到的傷害^ffffff，且移動中會獲得^00ff00俊足^ffffff效果，無視移動限制效果影響。"
SKILL_DETAIL_DESC_EX[11485] = "消耗自身大量內力，為目標或自身極大量^00ff00回復氣血值^ffffff，且回復大量體力。\r絕技過程全身^00ff00剛體^ffffff且^00ff00極大減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[11486] = "以幻影移的身形位移至目標身前，突進除了可以破除防御，還可將目標擊暈。\r此絕技可以^00ff00在空中使用^ffffff。\r絕技過程^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[11487] = "快速對足下踩踏，使附近所有單位陷入^e76041鈍足^ffffff狀態。在短暫的延時后，足下會產生猛烈的爆炸，將附近所有單位^e76041擊飛^ffffff。\r絕技過程全身^00ff00剛體^ffffff且^00ff00大量減免受到的傷害^ffffff。"
SKILL_DETAIL_DESC_EX[11488] = "驅動內力攻擊周圍敵人。同時自身會獲得短時^00ff00真氣護體^ffffff效果，此效果可以用內力抵擋部分自身受到的傷害，且其間無視^e76041點穴^ffffff效果影響，^00ff00真氣護體^ffffff效果僅在內力大于20%時存在。（比武場內持續時間會受到調整）"
SKILL_DETAIL_DESC_EX[11489] = "以蠱敵之術攻擊周圍單位，使敵人陷入^e76041鈍足^ffffff狀態。同時會借力向前方扔出一排生死符，使擊中的單位^e76041擊退^ffffff，并受到強烈的^e76041中毒^ffffff效果影響并進入走火入魔狀態。"
SKILL_DETAIL_DESC_EX[11491] = "消耗品，使用后能瞬間回復一定血量，可在戰斗中使用"
SKILL_DETAIL_DESC_EX[11493] = "消耗品，向目標方向扔出投擲物，被擊中的敵人將被眩暈3秒"
