PET_SKILL_DESC[1280] = {skilltype = 4, skilltext = "增加主人內功攻擊，持續5分鐘，效果受門徒自身內功攻擊影響。最大上限1000點。", desc = "能借助萬物靈動之息，彌補內力攻擊", idenhance = 0 }
PET_SKILL_DESC[1281] = {skilltype = 4, skilltext = "增加主人外功攻擊，持續5分鐘，效果受門徒自身外攻攻擊影響。最大上限1000點。", desc = "一種沖脈之術，能使其主人脈搏通暢，獲得襲盾之力", idenhance = 0 }
PET_SKILL_DESC[1282] = {skilltype = 4, skilltext = "增加主人內功抵禦，持續5分鐘，效果受門徒自身內功攻擊影響。最大上限1500點。", desc = "能使其主聚氣為丹的招式，以氣丹之力，抵禦外來之擊", idenhance = 0 }
