PET_SKILL_DESC[1304] = {skilltype = 5, skilltext = "使目標不能移動，持續4秒並受到傷害，傷害效果受門徒氣血上限影響", desc = "以冰寒的內力將敵人凍結，不可移動，故為冰封", idenhance = 0 }
PET_SKILL_DESC[1305] = {skilltype = 5, skilltext = "使目標不能移動，持續5分鐘", desc = "撒出一張網束縛住敵人，使其不能移動", idenhance = 0 }
PET_SKILL_DESC[1306] = {skilltype = 5, skilltext = "使目標不能移動，持續5分鐘", desc = "借助如鬼魅般的自然之力纏繞敵人，使其不能移動", idenhance = 0 }
PET_SKILL_DESC[1307] = {skilltype = 5, skilltext = "對目標衝鋒，造成#ra#外功攻擊傷害，並使目標不能移動，持續5分鐘", desc = "像野狼獵食一樣加速撞擊對手的招式", idenhance = 0 }
PET_SKILL_DESC[1314] = {skilltype = 6, skilltext = "降低目標內功攻擊，持續15秒，效果受門徒內功攻擊影響", desc = "此詛咒能使對手的內力不暢，傳聞是東洋巫王的密咒", idenhance = 0 }
PET_SKILL_DESC[1315] = {skilltype = 6, skilltext = "降低範圍內目標內功攻擊，持續15秒，效果受門徒內功攻擊影響", desc = "通過催脈之咒，使周遭之人呼吸混亂，內力不暢", idenhance = 0 }
PET_SKILL_DESC[1316] = {skilltype = 6, skilltext = "降低目標外功攻擊，持續15秒，效果受門徒外功攻擊影響", desc = "黑彝人的秘咒，能使對手產生幻覺，攻擊錯亂", idenhance = 0 }
PET_SKILL_DESC[1317] = {skilltype = 6, skilltext = "降低範圍內目標外功攻擊，持續15秒，效果受門徒外功攻擊影響", desc = "能使對方全身骨踝衰疲的詛咒，能使敵手下盤不穩", idenhance = 0 }
PET_SKILL_DESC[1318] = {skilltype = 6, skilltext = "降低目標內功防禦，持續15秒，效果受門徒內功攻擊影響", desc = "能阻礙對方小周天的詛咒，讓其無法將真氣運走", idenhance = 0 }
