PET_SKILL_DESC[1321] = {skilltype = 6, skilltext = "降低範圍內目標外功防禦，持續15秒，效果受門徒外功防禦影響", desc = "傳聞是妲己寫下的妖咒，有極大的妖邪之力，可以讓周圍的人難以防禦", idenhance = 0 }
PET_SKILL_DESC[1322] = {skilltype = 6, skilltext = "降低目標移動速度，持續15秒，效果受門徒氣血上限影響", desc = "但凡中此詛咒者，都會腳如灌鉛，身若系于磐石難以移動", idenhance = 0 }
PET_SKILL_DESC[1323] = {skilltype = 6, skilltext = "使目標中毒，每秒造成#sv1#點傷害，持續5分鐘", desc = "苗疆的咒語，此咒能使周圍的毒蟲攻擊對手，使其中毒", idenhance = 0 }
PET_SKILL_DESC[1324] = {skilltype = 6, skilltext = "使#r#米範圍內目標中毒，每秒造成#sv1#點傷害，持續5分鐘", desc = "獨龍族祭司所創的秘咒，此咒能催化空氣中的毒菇孢子，使範圍內的對手持續受到菌毒傷害", idenhance = 0 }
PET_SKILL_DESC[1325] = {skilltype = 6, skilltext = "使目標出血，每秒造成傷害，持續15秒，效果受門徒氣血上限影響", desc = "從波斯流傳過來的一種毒咒，能使對手流血不止", idenhance = 0 }
PET_SKILL_DESC[1326] = {skilltype = 6, skilltext = "使範圍內目標出血，每秒造成傷害，持續15秒，效果受門徒氣血上限影響", desc = "由古暹羅的降頭師帶入中原的詛咒，此咒相當邪惡，能使周遭對手舊創復發，血流不止", idenhance = 0 }
PET_SKILL_DESC[1327] = {skilltype = 6, skilltext = "使目標灼燒，每秒造成#sv1#點傷害，持續5分鐘", desc = "中原古老咒語，受祖咒的敵人會招來臟腑邪火，持續的灼燒", idenhance = 0 }
PET_SKILL_DESC[1328] = {skilltype = 6, skilltext = "使#r#米範圍內目標灼燒，每秒造成#sv1#點傷害，持續5分鐘", desc = "相傳是從地府流傳出來的詛咒，此詛咒能引出地府冥火，讓周圍的敵對者受到灼燒", idenhance = 0 }
PET_SKILL_DESC[1330] = {skilltype = 8, skilltext = "增加門徒力道屬性#sv1#點", desc = "通過“周天運行之法”以內功增強門徒的力量", idenhance = 0 }
PET_SKILL_DESC[1331] = {skilltype = 8, skilltext = "增加門徒體魄屬性#sv1#點", desc = "將內勁若潮湧般過繼給門徒，能增加門徒的體魄", idenhance = 0 }
PET_SKILL_DESC[1332] = {skilltype = 8, skilltext = "增加門徒筋骨屬性#sv1#點", desc = "以內力護住門徒的筋骨，從而增強其筋骨屬性", idenhance = 0 }
PET_SKILL_DESC[1333] = {skilltype = 8, skilltext = "增加門徒內勁屬性#sv1#點", desc = "幫助門徒將內力運轉于丹田，如若沉元，能提升其內勁屬性", idenhance = 0 }
PET_SKILL_DESC[1334] = {skilltype = 8, skilltext = "增加門徒氣海屬性#sv1#點", desc = "指引門徒氣游“大周天”，運轉全身內力，亦如聚流成海，能增加門徒氣海屬性", idenhance = 0 }
PET_SKILL_DESC[1335] = {skilltype = 8, skilltext = "增加門徒內功攻擊，效果受門徒內功攻擊影響。", desc = "將門徒內力引出，令其氣浪湧聚於全身各處“蓄勢待發”，能增加門徒內功攻擊力", idenhance = 0 }
PET_SKILL_DESC[1336] = {skilltype = 8, skilltext = "增加門徒外功攻擊，效果受門徒外功攻擊影響。", desc = "武當祖師爺所創的硬派氣功，能增加門徒外功攻擊力，因其當初以之劈斷盤松而得其名", idenhance = 0 }
PET_SKILL_DESC[1337] = {skilltype = 8, skilltext = "增加門徒內功防禦，效果受門徒內功攻擊影響。", desc = "此技名為“送潮”是因為它能卸掉對手的內功攻擊力，如大海送潮，提高了門徒內功防禦力", idenhance = 0 }
PET_SKILL_DESC[1338] = {skilltype = 8, skilltext = "增加門徒外功防禦，效果受門徒外功攻擊影響。", desc = "讓門徒屏氣于膚的武學，能使其膚堅若岩石，增加門徒的外功防禦力", idenhance = 0 }
PET_SKILL_DESC[1339] = {skilltype = 8, skilltext = "增加門徒氣血上限，效果受門徒氣血上限影響。", desc = "為門徒賦予此技，門徒提高其氣血上限，如同千峰競秀，撥霧而高", idenhance = 0 }
PET_SKILL_DESC[1342] = {skilltype = 8, skilltext = "提高門徒寒冰抗性#sv1#點", desc = "使門徒以內力之暖，融化冰雪之傷，此功取五行之道，行相克之理", idenhance = 0 }
PET_SKILL_DESC[1343] = {skilltype = 8, skilltext = "提高門徒火焰抗性#sv1#點", desc = "能令門徒將內力運至冰寒，減少其受到的火屬性傷害", idenhance = 0 }
PET_SKILL_DESC[1344] = {skilltype = 8, skilltext = "提高門徒腐毒抗性#sv1#點", desc = "門徒借用此招，能以百草之華抵禦部分毒傷", idenhance = 0 }
PET_SKILL_DESC[1345] = {skilltype = 8, skilltext = "提高門徒陰屬性傷害抗性#sv1#點", desc = "同取五行相克之道，將陰陽調和，以降低陰屬性對其的傷害", idenhance = 0 }
PET_SKILL_DESC[1346] = {skilltype = 8, skilltext = "提高門徒陽屬性傷害抗性#sv1#點", desc = "門徒若獲此決，能禦寒勁抵消掉部分陽屬性造成的傷害", idenhance = 0 }
PET_SKILL_DESC[1347] = {skilltype = 8, skilltext = "提高門徒玄屬性傷害抗性#sv1#點", desc = "主人使用此技的話，門徒能將受到的玄屬性傷害在體內削弱一部分", idenhance = 0 }
PET_SKILL_DESC[2522] = {skilltype = 7, skilltext = "合體時，額外增加#qh#的氣血給主人", desc = "此技可復蘇盤古殘留在夢裡的神思，混元而古老的力量", idenhance = 0 }
PET_SKILL_DESC[2523] = {skilltype = 7, skilltext = "合體時，額外增加#qh#的內力給主人", desc = "伏羲曾因震怒而以掌裂簡，此力道亦傳於其血統", idenhance = 0 }
PET_SKILL_DESC[2524] = {skilltype = 7, skilltext = "合體時，額外增加#qh#的外攻給主人", desc = "凡此血統者能引氣拉動螺祖的藏於其脈搏中的絲線，吸收其蘊含的強大力量", idenhance = 0 }
PET_SKILL_DESC[2525] = {skilltype = 7, skilltext = "合體時，額外增加#qh#的內攻給主人", desc = "皇帝在定坐時，呼出的一口真氣，若能行此真元，便能獲其助力", idenhance = 0 }
PET_SKILL_DESC[2526] = {skilltype = 7, skilltext = "合體時，額外增加#qh#的氣血和內力給主人", desc = "借助東皇戰甲上的碎片，只有此血統者能激發其中的神力，釋放其強大的抵禦", idenhance = 0 }
PET_SKILL_DESC[2527] = {skilltype = 7, skilltext = "額外使門徒詛咒招式增強#qh#", desc = "血統者從《祝融火咒》裡搜尋得來的一種咒文，有著強大的魔力", idenhance = 0 }
PET_SKILL_DESC[2528] = {skilltype = 7, skilltext = "額外使門徒輔助招式增強#qh#", desc = "神農制偶人驅鳥時，無意發現偶人有輔戰之用，於是便將其記載於自己的夢中，傳同血族之人學習", idenhance = 0 }
