PET_SKILL_DESC[2530] = {skilltype = 7, skilltext = "額外使門徒內攻招式增強#qh#", desc = "女媧祭月，浩氣天存，其祭品補天石所藏的神力，只有帶此血脈者能激發", idenhance = 0 }
PET_SKILL_DESC[2531] = {skilltype = 7, skilltext = "額外使門徒外攻招式增強#qh#", desc = "夸父追日的時候，曾聽到數聲鼓響，此鼓聲正是一直鼓舞夸父追日之神力，有著無窮的力量，只其血承者可聽到，不過他們也只能發揮出其中一點作用", idenhance = 0 }
