PET_SKILL_DESC[9068] = {skilltype = 4, skilltext = "尖牙和利爪是這種小生物最仰仗的武器，可以輕鬆撕開敵人的血肉之軀。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9069] = {skilltype = 4, skilltext = "捕頭們多年積累下來的鐵尺招式，進可攻、退可守。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9070] = {skilltype = 4, skilltext = "江湖流傳很廣的棍法，在街邊賣藝者處都可看到，但若真正領悟此棍法，也能發揮相當威力。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9071] = {skilltype = 4, skilltext = "白雕用力舞動翅膀卷起強力風暴對敵人造成傷害。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9133] = {skilltype = 4, skilltext = "對目標發動內功攻擊並造成額外的冰屬性傷害，傷害效果受門徒內功攻擊影響", desc = "化氣為冰，一旦釋放，能以冰暴之力重擊對手", idenhance = 0 }
PET_SKILL_DESC[9134] = {skilltype = 4, skilltext = "對目標發動內功攻擊並造成額外的毒屬性傷害，傷害效果受門徒內功攻擊影響", desc = "如狂犬一般撲向對手，同時附帶有獨特的陰毒攻擊", idenhance = 0 }
PET_SKILL_DESC[9135] = {skilltype = 4, skilltext = "對目標發動外功攻擊並造成額外的火屬性傷害，傷害效果受門徒內功攻擊影響。", desc = "以天罡之力，以“我”為心，攻擊周遭敵人，如同太陽釋放出光熱", idenhance = 0 }
PET_SKILL_DESC[9136] = {skilltype = 4, skilltext = "對目標發動外功攻擊並造成額外的土屬性傷害，傷害效果受門徒內功攻擊影響", desc = "黃帝長子玄囂所創的一招武學，可惜只剩殘篇", idenhance = 0 }
PET_SKILL_DESC[1284] = {skilltype = 4, skilltext = "增加主人體魄屬性，持續5分鐘，效果受門徒自身外攻能力影響。", desc = "如擂鼓般將真氣過繼給主人，讓其吐納平靜，動用自如", idenhance = 0 }
PET_SKILL_DESC[1285] = {skilltype = 4, skilltext = "增加主人體魄屬性，持續5分鐘，效果受門徒自身內功能力影響。", desc = "如擂鼓般將真氣過繼給主人，讓其吐納平靜，動用自如", idenhance = 0 }
PET_SKILL_DESC[9138] = {skilltype = 4, skilltext = "據說本是錘法，改為板斧招數後更為犀利。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9139] = {skilltype = 4, skilltext = "此套拳路專打人身上要穴，創始者為一附庸風雅的文士。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9140] = {skilltype = 4, skilltext = "有江河湖海的地方都可以見到這路招數，在水下使用威力更甚。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9145] = {skilltype = 4, skilltext = "一股神奇的力量潤澤心靈。", desc = "教主貓專屬技能", idenhance = 0 }
PET_SKILL_DESC[9147] = {skilltype = 4, skilltext = "哪怕無毒，這刺痛都已讓人難以忍受。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9148] = {skilltype = 3, skilltext = "此錘法寓意取張良與力士刺秦時奮力一擊，中者必粉身碎骨。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9367] = {skilltype = 2, skilltext = "少林72絕技之一，傳為達摩祖師所創，但貌似沒有學全。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9378] = {skilltype = 4, skilltext = "火炮之術，威懾力極強，據說可以摧毀任何東西。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9405] = {skilltype = 6, skilltext = "鎖住敵人的真氣，使目標5秒內不能使用技能。只對人物有效。", desc = "默默詛咒，折磨敵人，鎖住真氣，使人痛苦", idenhance = 0 }
PET_SKILL_DESC[9379] = {skilltype = 4, skilltext = "據傳為江湖中早已失傳的絕技。集門徒自身之真氣，為主人回復氣血值。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9637] = {skilltype = 3, skilltext = "利用全身力氣，擊暈敵人，使敵人3秒內不能有任何行動。", desc = "強大的功力，擊暈敵人，使其無任何還手之力", idenhance = 0 }
PET_SKILL_DESC[9648] = {skilltype = 2, skilltext = "利用全身內力，擊暈敵人，使敵人3秒內不能有任何行動。", desc = "強大的功力，擊暈敵人，使其無任何還手之力", idenhance = 0 }
PET_SKILL_DESC[9695] = {skilltype = 2, skilltext = "弑殺靈魂，使敵人魂飛魄散，受到傷害。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9696] = {skilltype = 3, skilltext = "用沾滿鮮血的靈驅嗜血，使敵人受到傷害。", desc = "門徒入門時的拿手技能", idenhance = 0 }
PET_SKILL_DESC[9834] = {skilltype = 1, skilltext = "怒火中燒，利用全身力氣，擊暈敵人，使敵人3秒內不能有任何行動。", desc = "強大的功力，擊暈敵人，使其無任何還手之力", idenhance = 0 }
PET_SKILL_DESC[9835] = {skilltype = 1, skilltext = "怒火中燒，利用全身內力，擊暈敵人，使敵人3秒內不能有任何行動。", desc = "強大的功力，擊暈敵人，使其無任何還手之力", idenhance = 0 }
PET_SKILL_DESC[9836] = {skilltype = 1, skilltext = "集中全身力氣，奮力一擊，擊飛敵人。", desc = "強大的功力，奮力一擊，擊飛敵人", idenhance = 0 }
PET_SKILL_DESC[9837] = {skilltype = 1, skilltext = "集中全身內力，奮力一擊，擊飛敵人。", desc = "強大的功力，奮力一擊，擊飛敵人", idenhance = 0 }
PET_SKILL_DESC[9838] = {skilltype = 1, skilltext = "弑殺敵人，利用自身強大的力氣撕裂敵人，使敵人血流不止，持續10秒，效果受門徒外功攻擊影響。最大上限為每秒1650點。", desc = "一種強大的技能，折磨敵人身心，使人血流不止", idenhance = 0 }
PET_SKILL_DESC[9839] = {skilltype = 1, skilltext = "弑殺敵人，利用自身強大的內力撕裂敵人，使敵人血流不止，持續10秒，效果受門徒內功攻擊影響。最大上限為每秒1650點。", desc = "一種強大的技能，折磨敵人身心，使人血流不止", idenhance = 0 }
