PET_SKILL_DESC[9841] = {skilltype = 1, skilltext = "", desc = "", idenhance = 0 }
PET_SKILL_DESC[9842] = {skilltype = 1, skilltext = "古老的密咒，記載著歸元補氣的咒文，恢復主人氣血，持續10秒，效果受門徒自身氣血上限影響。最大上限為每秒5000點。", desc = "據說江湖早已失傳的咒文", idenhance = 0 }
PET_SKILL_DESC[9843] = {skilltype = 1, skilltext = "", desc = "", idenhance = 0 }
PET_SKILL_DESC[9844] = {skilltype = 1, skilltext = "補中益氣，回復功力，恢復主人內力，持續10秒，效果受門徒自身氣血上限影響。最大上限為每秒2500點。", desc = "補中益氣，使人神清氣爽，重新煥發活力", idenhance = 0 }
PET_SKILL_DESC[9845] = {skilltype = 1, skilltext = "", desc = "", idenhance = 0 }
PET_SKILL_DESC[9846] = {skilltype = 1, skilltext = "利用自身強大的功力，瞬間使人恢復，恢復主人氣血，效果受門徒自身氣血上限影響。最大上限為45000點。", desc = "九子連心，歸元還魂，使人重新煥發活力", idenhance = 0 }
