PET_SKILL_DESC[9848] = {skilltype = 1, skilltext = "集中自身精力，向主人傳輸內力，恢復主人內力，效果受門徒自身氣血上限影響。最大上限為22500點。", desc = "據傳是一位俠者從一本江湖秘笈裡參悟出來的", idenhance = 0 }
