function RGBDecToHex(r,g,b)
	local hex
	local temp = --[[!AUTO_5446]]""
	local dec = {}

	dec[1] = --[[!AUTO_5447]]"0"
	dec[2] = --[[!AUTO_5448]]"1"
	dec[3] = --[[!AUTO_5449]]"2"
	dec[4] = --[[!AUTO_5450]]"3"
	dec[5] = --[[!AUTO_5451]]"4"
	dec[6] = --[[!AUTO_5452]]"5"
	dec[7] = --[[!AUTO_5453]]"6"
	dec[8] = --[[!AUTO_5454]]"7"
	dec[9] = --[[!AUTO_5455]]"8"
	dec[10] = --[[!AUTO_5456]]"9"
	dec[11] = --[[!AUTO_5457]]"a"
	dec[12] = --[[!AUTO_5458]]"b"
	dec[13] = --[[!AUTO_5459]]"c"
	dec[14] = --[[!AUTO_5460]]"d"
	dec[15] = --[[!AUTO_5461]]"e"
	dec[16] = --[[!AUTO_5462]]"f"

	if r <= 255 and g <= 255 and b <= 255 then
		return --[[!AUTO_5463]]"^" .. dec[math.floor(r/16)+1] .. dec[r%16+1] .. dec[math.floor(g/16)+1] .. dec[g%16+1] .. dec[math.floor(b/16)+1] .. dec[b%16+1]
	end
end


